            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, t_tg2_rr_01, t_tg2_rr_02
            real(wp) :: t_tg2_rr_12

            x0 = (d_a(1)*d_a(1))
            x1 = (d_a(2)*d_a(2))
            x2 = (d_a(3)*d_a(3))
            x3 = x0 + x1 + x2
            x4 = sqrt(x3)
            x5 = 1.0_wp/R_a
            x6 = exp(a1*(x4*x5 - 1.0_wp))
            x7 = a1*x5*x6
            x8 = x7/x4
            x9 = 1.0_wp/(x3*sqrt(x3))
            x10 = x7*x9
            x11 = d_a(2)*x10
            x12 = 1.0_wp/(R_a*R_a)
            x13 = (a1*a1)
            x14 = 1.0_wp/x3
            x15 = d_a(1)*d_a(2)*x12*x13*x14*x6 - d_a(1)*x11
            x16 = d_a(3)*x10
            x17 = d_a(1)*d_a(3)*x12*x13*x14*x6 - d_a(1)*x16
            x18 = x0*x6
            x19 = x12*x13
            x20 = x14*x19
            x21 = d_a(2)*d_a(3)*x12*x13*x14*x6 - d_a(3)*x11
            x22 = x20*x6
            x23 = d_a(1)*x10
            x24 = d_a(1)*x22
            x25 = (d_a(1)*d_a(1)*d_a(1))
            x26 = 3.0_wp*x7/(x3*x3*sqrt(x3))
            x27 = x25*x6
            x28 = (a1*a1*a1)*x9/(R_a*R_a*R_a)
            x29 = 3.0_wp*x19/(x3*x3)
            x30 = x18*x28
            x31 = x18*x29
            x32 = x0*x26
            x33 = d_a(2)*x22
            x34 = -x11 + x33
            x35 = d_a(2)*x30 - d_a(2)*x31 + d_a(2)*x32 + x34
            x36 = d_a(3)*x22
            x37 = -x16 + x36
            x38 = d_a(3)*x30 - d_a(3)*x31 + d_a(3)*x32 + x37
            x39 = d_a(2)*d_a(3)
            x40 = d_a(1)*x39
            x41 = x28*x6
            x42 = d_a(1)*x41
            x43 = x29*x6
            x44 = x26*x40 + x39*x42 - x40*x43
            x45 = d_a(1)*x1
            x46 = -x23 + x24
            x47 = x1*x42 + x26*x45 - x43*x45 + x46
            x48 = d_a(1)*x2
            x49 = x2*x42 + x26*x48 - x43*x48 + x46
            x50 = (d_a(2)*d_a(2)*d_a(2))
            x51 = d_a(3)*x1
            x52 = x26*x51 + x37 + x41*x51 - x43*x51
            x53 = d_a(2)*x2
            x54 = x26*x53 + x34 + x41*x53 - x43*x53
            x55 = (d_a(3)*d_a(3)*d_a(3))
            tg0 = tg0 + (-d_a(1)*v_a(1)*x8 - d_a(2)*v_a(2)*x8 - d_a(3)*v_a(3)*x8)
            tg1_r(1) = tg1_r(1) + (-v_a(1)*(-x0*x10 + x18*x20 + x8) - v_a(2)*x15 - v_a(3)*x17)
            tg1_r(2) = tg1_r(2) + (-v_a(1)*x15 - v_a(2)*(-x1*x10 + x1*x22 + x8) - v_a(3)*x21)
            tg1_r(3) = tg1_r(3) + (-v_a(1)*x17 - v_a(2)*x21 - v_a(3)*(-x10*x2 + x2*x22 + x8))
            tg2_rr(1, 1) = &
