            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, t_pd2_rr_01, t_pd2_rr_02, t_pd2_rr_12

            x0 = d_a(1)*d_b(1)
            x1 = d_a(2)*d_b(2)
            x2 = d_a(3)*d_b(3)
            x3 = 1.0_wp/R_a
            x4 = 1.0_wp/R_b
            x5 = x3*x4
            x6 = -x5*(x0 + x1 + x2) + 1.0_wp
            x7 = (x6*x6*x6*x6)
            x8 = (d_a(1)*d_a(1))
            x9 = (d_a(2)*d_a(2))
            x10 = (d_a(3)*d_a(3))
            x11 = x10 + x8 + x9
            x12 = sqrt(x11)
            x13 = (d_b(1)*d_b(1))
            x14 = (d_b(2)*d_b(2))
            x15 = (d_b(3)*d_b(3))
            x16 = x13 + x14 + x15
            x17 = sqrt(x16)
            x18 = exp(a2*(x12*x3 + x17*x4 - 2.0_wp))
            x19 = c_par*x18
            x20 = x19*x7
            x21 = x19*(x6*x6*x6)
            x22 = x21*x5
            x23 = 4.0_wp*x22
            x24 = 1.0_wp/x12
            x25 = a2*x20
            x26 = x25*x3
            x27 = x24*x26
            x28 = 1.0_wp/x17
            x29 = x25*x4
            x30 = x28*x29
            x31 = 1.0_wp/(R_a*R_a)
            x32 = x31*x8
            x33 = 1.0_wp/(R_b*R_b)
            x34 = (x6*x6)
            x35 = x19*x33*x34
            x36 = 12.0_wp*x35
            x37 = x31*x36
            x38 = 1.0_wp/x11
            x39 = (a2*a2)
            x40 = x20*x39
            x41 = x38*x40
            x42 = x13*x33
            x43 = 1.0_wp/x16
            x44 = x40*x43
            x45 = x26/(x11*sqrt(x11))
            x46 = x29/(x16*sqrt(x16))
            x47 = x0*x31
            x48 = 24.0_wp*x35
            x49 = a2*x21
            x50 = 8.0_wp*x49
            x51 = x24*x4
            x52 = x50*x51
            x53 = x28*x3
            x54 = x50*x53
            x55 = x33*x54
            x56 = 2.0_wp*x24*x28*x40*x5
            x57 = -8.0_wp*x22 + x27 + x30
            x58 = d_a(1)*d_a(2)
            x59 = d_b(1)*d_b(2)
            x60 = x31*x52
            x61 = 4.0_wp*x49
            x62 = d_a(1)*d_b(2)*x61
            x63 = x31*x51
            x64 = d_a(2)*d_b(1)
            x65 = x61*x63
            x66 = x33*x53
            x67 = x61*x66
            x68 = d_a(1)*d_a(3)
            x69 = d_b(1)*d_b(3)
            x70 = d_a(1)*d_b(3)
            x71 = d_a(3)*d_b(1)
            x72 = x31*x41
            x73 = x33*x44
            x74 = x31*x48
            x75 = d_a(2)*d_a(3)
            x76 = d_b(2)*d_b(3)
            x77 = d_a(2)*d_b(3)
            x78 = d_a(3)*d_b(2)
            pd0 = pd0 + (x20)
            pd1_r(1) = pd1_r(1) + (-d_a(1)*x23 + d_a(1)*x27 - d_b(1)*x23 + d_b(1)*x30)
            pd1_r(2) = pd1_r(2) + (-d_a(2)*x23 + d_a(2)*x27 - d_b(2)*x23 + d_b(2)*x30)
            pd1_r(3) = pd1_r(3) + (-d_a(3)*x23 + d_a(3)*x27 - d_b(3)*x23 + d_b(3)*x30)
            pd2_rr(1, 1) = &
               pd2_rr(1, 1) + (-x0*x55 + x0*x56 + x13*x37 - x13*x46 + x32*x36 + x32*x41 - x32*x52 &
               + x42*x44 - x42*x54 - x45*x8 + x47*x48 - x47*x52 + x57)
            t_pd2_rr_01 = &
               12.0_wp*c_par*d_a(1)*d_a(2)*x18*x31*x33*x34 + &
               c_par*d_a(1)*d_a(2)*x18*x31*x38*x39*x7 + &
               c_par*d_a(1)*d_b(2)*x18*x24*x28*x3*x39*x4*x7 + &
               12.0_wp*c_par*d_a(1)*d_b(2)*x18*x31*x33*x34 + &
               c_par*d_a(2)*d_b(1)*x18*x24*x28*x3*x39*x4*x7 + &
               12.0_wp*c_par*d_a(2)*d_b(1)*x18*x31*x33*x34 + &
               12.0_wp*c_par*d_b(1)*d_b(2)*x18*x31*x33*x34 + &
               c_par*d_b(1)*d_b(2)*x18*x33*x39*x43*x7 - x45*x58 - x46*x59 - x55*x59 - x58*x60 - &
               x62*x63 - x62*x66 - x64*x65 - x64*x67
            pd2_rr(1, 2) = pd2_rr(1, 2) + t_pd2_rr_01
            pd2_rr(2, 1) = pd2_rr(2, 1) + t_pd2_rr_01
            t_pd2_rr_02 = &
