            qn1_r_a(1, 2) = qn1_r_a(1, 2) + (x13)
            qn1_r_a(1, 3) = qn1_r_a(1, 3) + (x15)
            qn1_r_a(2, 1) = qn1_r_a(2, 1) + (x13)
            qn1_r_a(2, 2) = qn1_r_a(2, 2) + (a1*x1*x5*x6*x9 - x1*x10 - x8)
            qn1_r_a(2, 3) = qn1_r_a(2, 3) + (x17)
            qn1_r_a(3, 1) = qn1_r_a(3, 1) + (x15)
            qn1_r_a(3, 2) = qn1_r_a(3, 2) + (x17)
