            x26 = 1.0_wp/(x3*x3)
            x27 = x10*x25
            x28 = x0*x24
            x29 = -a1*d_a(2)*x5*x6*x9 + x17
            x30 = 3.0_wp*d_a(2)*x0*x11*x12*x26*x6 - d_a(2)*x27 - d_a(2)*x28 - x29
            x31 = -a1*d_a(3)*x5*x6*x9 + x19
