            qn1_r_a(1, 3) = qn1_r_a(1, 3) + (x20)
            qn1_r_a(2, 1) = qn1_r_a(2, 1) + (x18)
            qn1_r_a(2, 2) = qn1_r_a(2, 2) + (a1*x1*x5*x6*x9 - x1*x16 - x8)
            qn1_r_a(2, 3) = qn1_r_a(2, 3) + (x21)
            qn1_r_a(3, 1) = qn1_r_a(3, 1) + (x20)
            qn1_r_a(3, 2) = qn1_r_a(3, 2) + (x21)
