            x3 = (x2*x2*x2)
            x4 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            x5 = sqrt(((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))))
            x6 = exp(a2*(x0*x4 + x1*x5 - 2.0_wp))
            x7 = c_par*x6
            x8 = a2*(x2*x2*x2*x2)
            x9 = x0*x8/x4
            x10 = x7*x9
            x11 = x1*x8/x5
            x12 = x11*x7
            qn0_a(1) = qn0_a(1) + (4.0_wp*c_par*d_b(1)*x0*x1*x3*x6 - d_a(1)*x7*x9)
            qn0_a(2) = qn0_a(2) + (4.0_wp*c_par*d_b(2)*x0*x1*x3*x6 - d_a(2)*x10)
            qn0_a(3) = qn0_a(3) + (4.0_wp*c_par*d_b(3)*x0*x1*x3*x6 - d_a(3)*x10)
            qn0_b(1) = qn0_b(1) + (4.0_wp*c_par*d_a(1)*x0*x1*x3*x6 - d_b(1)*x11*x7)
            qn0_b(2) = qn0_b(2) + (4.0_wp*c_par*d_a(2)*x0*x1*x3*x6 - d_b(2)*x12)
            qn0_b(3) = qn0_b(3) + (4.0_wp*c_par*d_a(3)*x0*x1*x3*x6 - d_b(3)*x12)
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, x79, x80, x81, x82, x83, x84, x85, x86, x87, x88, x89, x90, x91
            real(wp) :: x92, x93

            x0 = 1.0_wp/R_a
            x1 = 1.0_wp/R_b
            x2 = d_a(1)*d_b(1)
            x3 = d_a(2)*d_b(2)
            x4 = d_a(3)*d_b(3)
            x5 = x0*x1
            x6 = -x5*(x2 + x3 + x4) + 1.0_wp
            x7 = (x6*x6*x6)
            x8 = (d_a(1)*d_a(1))
            x9 = (d_a(2)*d_a(2))
            x10 = (d_a(3)*d_a(3))
            x11 = x10 + x8 + x9
            x12 = sqrt(x11)
            x13 = (d_b(1)*d_b(1))
            x14 = (d_b(2)*d_b(2))
            x15 = (d_b(3)*d_b(3))
            x16 = x13 + x14 + x15
            x17 = sqrt(x16)
            x18 = exp(a2*(x0*x12 + x1*x17 - 2.0_wp))
            x19 = 1.0_wp/x12
            x20 = a2*x19
            x21 = c_par*x18
            x22 = x21*(x6*x6*x6*x6)
            x23 = x0*x22
            x24 = x20*x23
            x25 = 1.0_wp/x17
            x26 = a2*x25
            x27 = x1*x22
            x28 = x26*x27
            x29 = 1.0_wp/(R_b*R_b)
            x30 = x13*x29
            x31 = 1.0_wp/(R_a*R_a)
            x32 = 12.0_wp*x21*x31*(x6*x6)
            x33 = a2*x23/(x11*sqrt(x11))
            x34 = x31*x8
            x35 = (a2*a2)*x22
            x36 = x35/x11
            x37 = x21*x7
            x38 = 8.0_wp*x37
            x39 = x2*x38
            x40 = x1*x20
            x41 = x31*x40
            x42 = 4.0_wp*x37
            x43 = x42*x5
            x44 = -x24 + x43
            x45 = x29*x32
            x46 = x40*x42
            x47 = x0*x26
            x48 = x42*x47
            x49 = x19*x25*x35*x5
            x50 = -x2*x45 - x2*x49 + x30*x48 + x34*x46
            x51 = d_b(2)*x45
            x52 = d_a(2)*d_b(1)
            x53 = d_a(1)*d_a(2)
            x54 = x31*x46
            x55 = d_b(1)*d_b(2)
            x56 = x29*x48
            x57 = x53*x54 + x55*x56
            x58 = -d_a(1)*x51 - x49*x52 + x57
            x59 = x31*x36
            x60 = d_a(1)*x54
            x61 = -d_b(1)*x51 + d_b(2)*x60 + x33*x53 + x52*x54 - x53*x59
            x62 = d_b(3)*x45
            x63 = d_a(3)*d_b(1)
            x64 = d_a(1)*d_a(3)
            x65 = d_b(1)*d_b(3)
            x66 = x54*x64 + x56*x65
            x67 = -d_a(1)*x62 - x49*x63 + x66
            x68 = -d_b(1)*x62 + d_b(3)*x60 + x33*x64 + x54*x63 - x59*x64
            x69 = d_b(1)*x45
            x70 = d_b(2)*x49
            x71 = -d_a(1)*x70 - d_a(2)*x69 + x57
            x72 = x38*x41
            x73 = x14*x56 - x3*x45 - x3*x49 + x54*x9
