            qn1_r_a(3, 1) = qn1_r_a(3, 1) + (x68 + x82)
            qn1_r_a(3, 2) = qn1_r_a(3, 2) + (x80 + x83)
            qn1_r_a(3, 3) = qn1_r_a(3, 3) + (x10*x33 - x10*x59 - x15*x45 + x4*x72 + x44 + x84)
            qn1_r_b(1, 1) = qn1_r_b(1, 1) + (x13*x85 - x30*x86 + x39*x87 - x45*x8 + x50 + x88)
            qn1_r_b(1, 2) = qn1_r_b(1, 2) + (x71 + x90)
