            qq0_aa(1, 3) = qq0_aa(1, 3) + t_qq0_aa_02
            qq0_aa(3, 1) = qq0_aa(3, 1) + t_qq0_aa_02
            qq0_aa(2, 2) = qq0_aa(2, 2) + (x1*x13 - x1*x9 + x8)
            t_qq0_aa_12 = d_a(2)*d_a(3)*x10*x11*x12*x6 - d_a(2)*d_a(3)*x9
