   !> Lift the accumulated tensors to the level-set nuclear gradient.
   !>
   !> With ``S = -log PD`` and one retained nucleus A,
   !>
   !>    f{k+1}_..._rA(i1..ik, beta) = d/dR_A,beta  d^k S / dr_i1..dr_ik
   !>
   !> Two accumulated families feed it: `pd*` (`*_term_eval` /
   !> `cfc_pair_spatial_eval`, an aggregate) and `qn*` (`*_nuclear_eval`, atom
   !> A's own share).  No direction vector is involved, so a caller that wants
   !> only the nuclear gradient never touches the contracted families.
   !>
   !> Call once per atom A per evaluation point, i.e. O(n_active) in total.
   !>
   !> @param[in]    pd0        Accumulated order-0 spatial derivative of PD
   !> @param[in]    pd1_r      Accumulated order-1 spatial derivative of PD
   !> @param[in]    pd2_rr     Accumulated order-2 spatial derivative of PD
   !> @param[in]    pd3_rrr    Accumulated order-3 spatial derivative of PD
   !> @param[in]    qn0        Atom-A d/dR_A of the order-0 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    qn1_r      Atom-A d/dR_A of the order-1 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    qn2_rr     Atom-A d/dR_A of the order-2 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    qn3_rrr    Atom-A d/dR_A of the order-3 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    max_deriv  Highest spatial-derivative order to lift (0..3); a larger value is
   !>                          treated as 3
   !> @param[out]   f1_rA      d/dR_A of the order-0 spatial derivative of the level set; trailing
   !>                          index is the nuclear component
   !> @param[out]   f2_r_rA    d/dR_A of the order-1 spatial derivative of the level set; trailing
   !>                          index is the nuclear component
   !> @param[out]   f3_rr_rA   d/dR_A of the order-2 spatial derivative of the level set; trailing
   !>                          index is the nuclear component
   !> @param[out]   f4_rrr_rA  d/dR_A of the order-3 spatial derivative of the level set; trailing
   !>                          index is the nuclear component
   pure subroutine cfc_nuclear_eval(pd0, pd1_r, pd2_rr, pd3_rrr, qn0, qn1_r, qn2_rr, qn3_rrr, &
                                    max_deriv, f1_rA, f2_r_rA, f3_rr_rA, f4_rrr_rA)
      !> Accumulated order-0 spatial derivative of PD
      real(wp), intent(in) :: pd0
      !> Accumulated order-1 spatial derivative of PD
      real(wp), intent(in) :: pd1_r(3)
      !> Accumulated order-2 spatial derivative of PD
      real(wp), intent(in) :: pd2_rr(3, 3)
      !> Accumulated order-3 spatial derivative of PD
      real(wp), intent(in) :: pd3_rrr(3, 3, 3)
      !> Atom-A d/dR_A of the order-0 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn0(3)
      !> Atom-A d/dR_A of the order-1 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn1_r(3, 3)
      !> Atom-A d/dR_A of the order-2 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn2_rr(3, 3, 3)
      !> Atom-A d/dR_A of the order-3 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn3_rrr(3, 3, 3, 3)
      !> Highest spatial-derivative order to lift (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> d/dR_A of the order-0 spatial derivative of the level set; trailing index is the nuclear
      !> component
      real(wp), intent(out) :: f1_rA(3)
      !> d/dR_A of the order-1 spatial derivative of the level set; trailing index is the nuclear
      !> component
      real(wp), intent(out) :: f2_r_rA(3, 3)
      !> d/dR_A of the order-2 spatial derivative of the level set; trailing index is the nuclear
      !> component
      real(wp), intent(out) :: f3_rr_rA(3, 3, 3)
      !> d/dR_A of the order-3 spatial derivative of the level set; trailing index is the nuclear
      !> component
      real(wp), intent(out) :: f4_rrr_rA(3, 3, 3, 3)

      !> Reciprocal of the total pseudo-density
      real(wp) :: inv_pd

      ! Unconditional: the max_deriv dispatch below writes only the orders it
      ! was asked for, so every higher-order result must already be defined.
      f1_rA = 0.0_wp
      f2_r_rA = 0.0_wp
      f3_rr_rA = 0.0_wp
      f4_rrr_rA = 0.0_wp

      if (pd0 <= 0.0_wp) return
      inv_pd = 1.0_wp/pd0

      select case (max_deriv)
      case (0)
         block
            f1_rA(1) = -inv_pd*qn0(1)
            f1_rA(2) = -inv_pd*qn0(2)
            f1_rA(3) = -inv_pd*qn0(3)
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3

            x0 = (inv_pd*inv_pd)
            x1 = pd1_r(1)*x0
            x2 = pd1_r(2)*x0
            x3 = pd1_r(3)*x0
            f1_rA(1) = -inv_pd*qn0(1)
            f1_rA(2) = -inv_pd*qn0(2)
            f1_rA(3) = -inv_pd*qn0(3)
            f2_r_rA(1, 1) = -inv_pd*qn1_r(1, 1) + qn0(1)*x1
            f2_r_rA(1, 2) = -inv_pd*qn1_r(1, 2) + qn0(2)*x1
            f2_r_rA(1, 3) = -inv_pd*qn1_r(1, 3) + qn0(3)*x1
            f2_r_rA(2, 1) = -inv_pd*qn1_r(2, 1) + qn0(1)*x2
            f2_r_rA(2, 2) = -inv_pd*qn1_r(2, 2) + qn0(2)*x2
            f2_r_rA(2, 3) = -inv_pd*qn1_r(2, 3) + qn0(3)*x2
            f2_r_rA(3, 1) = -inv_pd*qn1_r(3, 1) + qn0(1)*x3
            f2_r_rA(3, 2) = -inv_pd*qn1_r(3, 2) + qn0(2)*x3
            f2_r_rA(3, 3) = -inv_pd*qn1_r(3, 3) + qn0(3)*x3
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14
            real(wp) :: t_f3_rr_rA_010, t_f3_rr_rA_011, t_f3_rr_rA_012, t_f3_rr_rA_020
            real(wp) :: t_f3_rr_rA_021, t_f3_rr_rA_022, t_f3_rr_rA_120, t_f3_rr_rA_121
            real(wp) :: t_f3_rr_rA_122

            x0 = (inv_pd*inv_pd)
            x1 = pd1_r(1)*x0
            x2 = pd1_r(2)*x0
            x3 = pd1_r(3)*x0
            x4 = 2.0_wp*x1
            x5 = 2.0_wp*(inv_pd*inv_pd*inv_pd)
            x6 = -(pd1_r(1)*pd1_r(1))*x5 + pd2_rr(1, 1)*x0
            x7 = pd1_r(1)*x5
            x8 = -pd1_r(2)*x7 + pd2_rr(1, 2)*x0
            x9 = -pd1_r(3)*x7 + pd2_rr(1, 3)*x0
            x10 = 2.0_wp*x2
            x11 = -(pd1_r(2)*pd1_r(2))*x5 + pd2_rr(2, 2)*x0
            x12 = -pd1_r(2)*pd1_r(3)*x5 + pd2_rr(2, 3)*x0
            x13 = 2.0_wp*x3
            x14 = -(pd1_r(3)*pd1_r(3))*x5 + pd2_rr(3, 3)*x0
            f1_rA(1) = -inv_pd*qn0(1)
            f1_rA(2) = -inv_pd*qn0(2)
            f1_rA(3) = -inv_pd*qn0(3)
            f2_r_rA(1, 1) = -inv_pd*qn1_r(1, 1) + qn0(1)*x1
            f2_r_rA(1, 2) = -inv_pd*qn1_r(1, 2) + qn0(2)*x1
            f2_r_rA(1, 3) = -inv_pd*qn1_r(1, 3) + qn0(3)*x1
            f2_r_rA(2, 1) = -inv_pd*qn1_r(2, 1) + qn0(1)*x2
            f2_r_rA(2, 2) = -inv_pd*qn1_r(2, 2) + qn0(2)*x2
            f2_r_rA(2, 3) = -inv_pd*qn1_r(2, 3) + qn0(3)*x2
            f2_r_rA(3, 1) = -inv_pd*qn1_r(3, 1) + qn0(1)*x3
            f2_r_rA(3, 2) = -inv_pd*qn1_r(3, 2) + qn0(2)*x3
            f2_r_rA(3, 3) = -inv_pd*qn1_r(3, 3) + qn0(3)*x3
            f3_rr_rA(1, 1, 1) = -inv_pd*qn2_rr(1, 1, 1) + qn0(1)*x6 + qn1_r(1, 1)*x4
            f3_rr_rA(1, 1, 2) = -inv_pd*qn2_rr(1, 1, 2) + qn0(2)*x6 + qn1_r(1, 2)*x4
            f3_rr_rA(1, 1, 3) = -inv_pd*qn2_rr(1, 1, 3) + qn0(3)*x6 + qn1_r(1, 3)*x4
            t_f3_rr_rA_010 = -inv_pd*qn2_rr(1, 2, 1) + qn0(1)*x8 + qn1_r(1, 1)*x2 + qn1_r(2, 1)*x1
            f3_rr_rA(1, 2, 1) = t_f3_rr_rA_010
            f3_rr_rA(2, 1, 1) = t_f3_rr_rA_010
            t_f3_rr_rA_011 = -inv_pd*qn2_rr(1, 2, 2) + qn0(2)*x8 + qn1_r(1, 2)*x2 + qn1_r(2, 2)*x1
            f3_rr_rA(1, 2, 2) = t_f3_rr_rA_011
            f3_rr_rA(2, 1, 2) = t_f3_rr_rA_011
            t_f3_rr_rA_012 = -inv_pd*qn2_rr(1, 2, 3) + qn0(3)*x8 + qn1_r(1, 3)*x2 + qn1_r(2, 3)*x1
            f3_rr_rA(1, 2, 3) = t_f3_rr_rA_012
            f3_rr_rA(2, 1, 3) = t_f3_rr_rA_012
            t_f3_rr_rA_020 = -inv_pd*qn2_rr(1, 3, 1) + qn0(1)*x9 + qn1_r(1, 1)*x3 + qn1_r(3, 1)*x1
            f3_rr_rA(1, 3, 1) = t_f3_rr_rA_020
            f3_rr_rA(3, 1, 1) = t_f3_rr_rA_020
            t_f3_rr_rA_021 = -inv_pd*qn2_rr(1, 3, 2) + qn0(2)*x9 + qn1_r(1, 2)*x3 + qn1_r(3, 2)*x1
            f3_rr_rA(1, 3, 2) = t_f3_rr_rA_021
            f3_rr_rA(3, 1, 2) = t_f3_rr_rA_021
            t_f3_rr_rA_022 = -inv_pd*qn2_rr(1, 3, 3) + qn0(3)*x9 + qn1_r(1, 3)*x3 + qn1_r(3, 3)*x1
            f3_rr_rA(1, 3, 3) = t_f3_rr_rA_022
            f3_rr_rA(3, 1, 3) = t_f3_rr_rA_022
            f3_rr_rA(2, 2, 1) = -inv_pd*qn2_rr(2, 2, 1) + qn0(1)*x11 + qn1_r(2, 1)*x10
            f3_rr_rA(2, 2, 2) = -inv_pd*qn2_rr(2, 2, 2) + qn0(2)*x11 + qn1_r(2, 2)*x10
            f3_rr_rA(2, 2, 3) = -inv_pd*qn2_rr(2, 2, 3) + qn0(3)*x11 + qn1_r(2, 3)*x10
            t_f3_rr_rA_120 = -inv_pd*qn2_rr(2, 3, 1) + qn0(1)*x12 + qn1_r(2, 1)*x3 + qn1_r(3, 1)*x2
            f3_rr_rA(2, 3, 1) = t_f3_rr_rA_120
            f3_rr_rA(3, 2, 1) = t_f3_rr_rA_120
            t_f3_rr_rA_121 = -inv_pd*qn2_rr(2, 3, 2) + qn0(2)*x12 + qn1_r(2, 2)*x3 + qn1_r(3, 2)*x2
            f3_rr_rA(2, 3, 2) = t_f3_rr_rA_121
            f3_rr_rA(3, 2, 2) = t_f3_rr_rA_121
            t_f3_rr_rA_122 = -inv_pd*qn2_rr(2, 3, 3) + qn0(3)*x12 + qn1_r(2, 3)*x3 + qn1_r(3, 3)*x2
            f3_rr_rA(2, 3, 3) = t_f3_rr_rA_122
            f3_rr_rA(3, 2, 3) = t_f3_rr_rA_122
            f3_rr_rA(3, 3, 1) = -inv_pd*qn2_rr(3, 3, 1) + qn0(1)*x14 + qn1_r(3, 1)*x13
            f3_rr_rA(3, 3, 2) = -inv_pd*qn2_rr(3, 3, 2) + qn0(2)*x14 + qn1_r(3, 2)*x13
            f3_rr_rA(3, 3, 3) = -inv_pd*qn2_rr(3, 3, 3) + qn0(3)*x14 + qn1_r(3, 3)*x13
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, t_f3_rr_rA_010, t_f3_rr_rA_011
            real(wp) :: t_f3_rr_rA_012, t_f3_rr_rA_020, t_f3_rr_rA_021, t_f3_rr_rA_022
            real(wp) :: t_f3_rr_rA_120, t_f3_rr_rA_121, t_f3_rr_rA_122, t_f4_rrr_rA_0010
            real(wp) :: t_f4_rrr_rA_0011, t_f4_rrr_rA_0012, t_f4_rrr_rA_0020, t_f4_rrr_rA_0021
            real(wp) :: t_f4_rrr_rA_0022, t_f4_rrr_rA_0110, t_f4_rrr_rA_0111, t_f4_rrr_rA_0112
            real(wp) :: t_f4_rrr_rA_0120, t_f4_rrr_rA_0121, t_f4_rrr_rA_0122, t_f4_rrr_rA_0220
            real(wp) :: t_f4_rrr_rA_0221, t_f4_rrr_rA_0222, t_f4_rrr_rA_1120, t_f4_rrr_rA_1121
            real(wp) :: t_f4_rrr_rA_1122, t_f4_rrr_rA_1220, t_f4_rrr_rA_1221, t_f4_rrr_rA_1222

            x0 = (inv_pd*inv_pd)
            x1 = pd1_r(1)*x0
            x2 = pd1_r(2)*x0
            x3 = pd1_r(3)*x0
            x4 = 2.0_wp*x1
            x5 = (pd1_r(1)*pd1_r(1))
            x6 = (inv_pd*inv_pd*inv_pd)
            x7 = 2.0_wp*x6
            x8 = pd2_rr(1, 1)*x0 - x5*x7
            x9 = pd1_r(1)*x7
            x10 = -pd1_r(2)*x9 + pd2_rr(1, 2)*x0
            x11 = -pd1_r(3)*x9 + pd2_rr(1, 3)*x0
            x12 = 2.0_wp*x2
            x13 = (pd1_r(2)*pd1_r(2))
            x14 = pd2_rr(2, 2)*x0 - x13*x7
            x15 = pd1_r(2)*pd1_r(3)
            x16 = pd2_rr(2, 3)*x0 - x15*x7
            x17 = 2.0_wp*x3
            x18 = (pd1_r(3)*pd1_r(3))
            x19 = pd2_rr(3, 3)*x0 - x18*x7
            x20 = 3.0_wp*x1
            x21 = 6.0_wp*x5
            x22 = 3.0_wp*pd2_rr(1, 1)*x0 - x21*x6
            x23 = 4.0_wp*x6
            x24 = pd1_r(1)*x23
            x25 = (inv_pd*inv_pd*inv_pd*inv_pd)
            x26 = -pd2_rr(1, 1)*x7 + x21*x25
            x27 = pd1_r(1)*x26 - pd2_rr(1, 1)*x24 + pd3_rrr(1, 1, 1)*x0
            x28 = -pd1_r(2)*x24 + 2.0_wp*pd2_rr(1, 2)*x0
            x29 = pd1_r(2)*x26 - pd2_rr(1, 2)*x24 + pd3_rrr(1, 1, 2)*x0
            x30 = -pd1_r(3)*x24 + 2.0_wp*pd2_rr(1, 3)*x0
            x31 = pd1_r(3)*x26 - pd2_rr(1, 3)*x24 + pd3_rrr(1, 1, 3)*x0
            x32 = pd2_rr(2, 2)*x7
            x33 = pd2_rr(1, 2)*x7
            x34 = 6.0_wp*x25
            x35 = pd1_r(1)*x34
            x36 = pd1_r(2)*x35 - x33
            x37 = -pd1_r(1)*x32 - pd1_r(2)*x33 + pd1_r(2)*x36 + pd3_rrr(1, 2, 2)*x0
            x38 = pd2_rr(2, 3)*x7
            x39 = pd2_rr(1, 3)*x7
            x40 = -pd1_r(1)*x38 - pd1_r(2)*x39 + pd1_r(3)*x36 + pd3_rrr(1, 2, 3)*x0
            x41 = pd2_rr(3, 3)*x7
            x42 = -pd1_r(1)*x41 - pd1_r(3)*x39 + pd1_r(3)*(pd1_r(3)*x35 - x39) + pd3_rrr(1, 3, 3)*x0
            x43 = 3.0_wp*x2
            x44 = 6.0_wp*x13
            x45 = 3.0_wp*pd2_rr(2, 2)*x0 - x44*x6
            x46 = pd1_r(2)*x23
            x47 = x25*x44 - x32
            x48 = pd1_r(2)*x47 - pd2_rr(2, 2)*x46 + pd3_rrr(2, 2, 2)*x0
            x49 = 2.0_wp*pd2_rr(2, 3)*x0 - x15*x23
            x50 = pd1_r(3)*x47 - pd2_rr(2, 3)*x46 + pd3_rrr(2, 2, 3)*x0
            x51 = -pd1_r(2)*x41 - pd1_r(3)*x38 + pd1_r(3)*(x15*x34 - x38) + pd3_rrr(2, 3, 3)*x0
            x52 = 3.0_wp*x3
            x53 = 6.0_wp*x18
            x54 = 3.0_wp*pd2_rr(3, 3)*x0 - x53*x6
            x55 = -pd1_r(3)*pd2_rr(3, 3)*x23 + pd1_r(3)*(x25*x53 - x41) + pd3_rrr(3, 3, 3)*x0
            f1_rA(1) = -inv_pd*qn0(1)
            f1_rA(2) = -inv_pd*qn0(2)
            f1_rA(3) = -inv_pd*qn0(3)
            f2_r_rA(1, 1) = -inv_pd*qn1_r(1, 1) + qn0(1)*x1
            f2_r_rA(1, 2) = -inv_pd*qn1_r(1, 2) + qn0(2)*x1
            f2_r_rA(1, 3) = -inv_pd*qn1_r(1, 3) + qn0(3)*x1
            f2_r_rA(2, 1) = -inv_pd*qn1_r(2, 1) + qn0(1)*x2
            f2_r_rA(2, 2) = -inv_pd*qn1_r(2, 2) + qn0(2)*x2
            f2_r_rA(2, 3) = -inv_pd*qn1_r(2, 3) + qn0(3)*x2
            f2_r_rA(3, 1) = -inv_pd*qn1_r(3, 1) + qn0(1)*x3
            f2_r_rA(3, 2) = -inv_pd*qn1_r(3, 2) + qn0(2)*x3
            f2_r_rA(3, 3) = -inv_pd*qn1_r(3, 3) + qn0(3)*x3
            f3_rr_rA(1, 1, 1) = -inv_pd*qn2_rr(1, 1, 1) + qn0(1)*x8 + qn1_r(1, 1)*x4
            f3_rr_rA(1, 1, 2) = -inv_pd*qn2_rr(1, 1, 2) + qn0(2)*x8 + qn1_r(1, 2)*x4
            f3_rr_rA(1, 1, 3) = -inv_pd*qn2_rr(1, 1, 3) + qn0(3)*x8 + qn1_r(1, 3)*x4
            t_f3_rr_rA_010 = -inv_pd*qn2_rr(1, 2, 1) + qn0(1)*x10 + qn1_r(1, 1)*x2 + qn1_r(2, 1)*x1
            f3_rr_rA(1, 2, 1) = t_f3_rr_rA_010
            f3_rr_rA(2, 1, 1) = t_f3_rr_rA_010
            t_f3_rr_rA_011 = -inv_pd*qn2_rr(1, 2, 2) + qn0(2)*x10 + qn1_r(1, 2)*x2 + qn1_r(2, 2)*x1
            f3_rr_rA(1, 2, 2) = t_f3_rr_rA_011
            f3_rr_rA(2, 1, 2) = t_f3_rr_rA_011
            t_f3_rr_rA_012 = -inv_pd*qn2_rr(1, 2, 3) + qn0(3)*x10 + qn1_r(1, 3)*x2 + qn1_r(2, 3)*x1
            f3_rr_rA(1, 2, 3) = t_f3_rr_rA_012
            f3_rr_rA(2, 1, 3) = t_f3_rr_rA_012
            t_f3_rr_rA_020 = -inv_pd*qn2_rr(1, 3, 1) + qn0(1)*x11 + qn1_r(1, 1)*x3 + qn1_r(3, 1)*x1
            f3_rr_rA(1, 3, 1) = t_f3_rr_rA_020
            f3_rr_rA(3, 1, 1) = t_f3_rr_rA_020
            t_f3_rr_rA_021 = -inv_pd*qn2_rr(1, 3, 2) + qn0(2)*x11 + qn1_r(1, 2)*x3 + qn1_r(3, 2)*x1
            f3_rr_rA(1, 3, 2) = t_f3_rr_rA_021
            f3_rr_rA(3, 1, 2) = t_f3_rr_rA_021
            t_f3_rr_rA_022 = -inv_pd*qn2_rr(1, 3, 3) + qn0(3)*x11 + qn1_r(1, 3)*x3 + qn1_r(3, 3)*x1
            f3_rr_rA(1, 3, 3) = t_f3_rr_rA_022
            f3_rr_rA(3, 1, 3) = t_f3_rr_rA_022
            f3_rr_rA(2, 2, 1) = -inv_pd*qn2_rr(2, 2, 1) + qn0(1)*x14 + qn1_r(2, 1)*x12
            f3_rr_rA(2, 2, 2) = -inv_pd*qn2_rr(2, 2, 2) + qn0(2)*x14 + qn1_r(2, 2)*x12
            f3_rr_rA(2, 2, 3) = -inv_pd*qn2_rr(2, 2, 3) + qn0(3)*x14 + qn1_r(2, 3)*x12
            t_f3_rr_rA_120 = -inv_pd*qn2_rr(2, 3, 1) + qn0(1)*x16 + qn1_r(2, 1)*x3 + qn1_r(3, 1)*x2
            f3_rr_rA(2, 3, 1) = t_f3_rr_rA_120
            f3_rr_rA(3, 2, 1) = t_f3_rr_rA_120
            t_f3_rr_rA_121 = -inv_pd*qn2_rr(2, 3, 2) + qn0(2)*x16 + qn1_r(2, 2)*x3 + qn1_r(3, 2)*x2
            f3_rr_rA(2, 3, 2) = t_f3_rr_rA_121
            f3_rr_rA(3, 2, 2) = t_f3_rr_rA_121
            t_f3_rr_rA_122 = -inv_pd*qn2_rr(2, 3, 3) + qn0(3)*x16 + qn1_r(2, 3)*x3 + qn1_r(3, 3)*x2
            f3_rr_rA(2, 3, 3) = t_f3_rr_rA_122
            f3_rr_rA(3, 2, 3) = t_f3_rr_rA_122
            f3_rr_rA(3, 3, 1) = -inv_pd*qn2_rr(3, 3, 1) + qn0(1)*x19 + qn1_r(3, 1)*x17
            f3_rr_rA(3, 3, 2) = -inv_pd*qn2_rr(3, 3, 2) + qn0(2)*x19 + qn1_r(3, 2)*x17
            f3_rr_rA(3, 3, 3) = -inv_pd*qn2_rr(3, 3, 3) + qn0(3)*x19 + qn1_r(3, 3)*x17
            f4_rrr_rA(1, 1, 1, 1) = &
               -inv_pd*qn3_rrr(1, 1, 1, 1) + qn0(1)*x27 + qn1_r(1, 1)*x22 + qn2_rr(1, 1, 1)*x20
            f4_rrr_rA(1, 1, 1, 2) = &
               -inv_pd*qn3_rrr(1, 1, 1, 2) + qn0(2)*x27 + qn1_r(1, 2)*x22 + qn2_rr(1, 1, 2)*x20
            f4_rrr_rA(1, 1, 1, 3) = &
               -inv_pd*qn3_rrr(1, 1, 1, 3) + qn0(3)*x27 + qn1_r(1, 3)*x22 + qn2_rr(1, 1, 3)*x20
            t_f4_rrr_rA_0010 = &
               -inv_pd*qn3_rrr(1, 1, 2, 1) + qn0(1)*x29 + qn1_r(1, 1)*x28 + qn1_r(2, 1)*x8 + &
               qn2_rr(1, 1, 1)*x2 + qn2_rr(1, 2, 1)*x4
            f4_rrr_rA(1, 1, 2, 1) = t_f4_rrr_rA_0010
            f4_rrr_rA(1, 2, 1, 1) = t_f4_rrr_rA_0010
            f4_rrr_rA(2, 1, 1, 1) = t_f4_rrr_rA_0010
            t_f4_rrr_rA_0011 = &
               -inv_pd*qn3_rrr(1, 1, 2, 2) + qn0(2)*x29 + qn1_r(1, 2)*x28 + qn1_r(2, 2)*x8 + &
               qn2_rr(1, 1, 2)*x2 + qn2_rr(1, 2, 2)*x4
            f4_rrr_rA(1, 1, 2, 2) = t_f4_rrr_rA_0011
            f4_rrr_rA(1, 2, 1, 2) = t_f4_rrr_rA_0011
            f4_rrr_rA(2, 1, 1, 2) = t_f4_rrr_rA_0011
            t_f4_rrr_rA_0012 = &
               -inv_pd*qn3_rrr(1, 1, 2, 3) + qn0(3)*x29 + qn1_r(1, 3)*x28 + qn1_r(2, 3)*x8 + &
               qn2_rr(1, 1, 3)*x2 + qn2_rr(1, 2, 3)*x4
            f4_rrr_rA(1, 1, 2, 3) = t_f4_rrr_rA_0012
            f4_rrr_rA(1, 2, 1, 3) = t_f4_rrr_rA_0012
            f4_rrr_rA(2, 1, 1, 3) = t_f4_rrr_rA_0012
            t_f4_rrr_rA_0020 = &
               -inv_pd*qn3_rrr(1, 1, 3, 1) + qn0(1)*x31 + qn1_r(1, 1)*x30 + qn1_r(3, 1)*x8 + &
               qn2_rr(1, 1, 1)*x3 + qn2_rr(1, 3, 1)*x4
            f4_rrr_rA(1, 1, 3, 1) = t_f4_rrr_rA_0020
            f4_rrr_rA(1, 3, 1, 1) = t_f4_rrr_rA_0020
            f4_rrr_rA(3, 1, 1, 1) = t_f4_rrr_rA_0020
            t_f4_rrr_rA_0021 = &
               -inv_pd*qn3_rrr(1, 1, 3, 2) + qn0(2)*x31 + qn1_r(1, 2)*x30 + qn1_r(3, 2)*x8 + &
               qn2_rr(1, 1, 2)*x3 + qn2_rr(1, 3, 2)*x4
            f4_rrr_rA(1, 1, 3, 2) = t_f4_rrr_rA_0021
            f4_rrr_rA(1, 3, 1, 2) = t_f4_rrr_rA_0021
            f4_rrr_rA(3, 1, 1, 2) = t_f4_rrr_rA_0021
            t_f4_rrr_rA_0022 = &
               -inv_pd*qn3_rrr(1, 1, 3, 3) + qn0(3)*x31 + qn1_r(1, 3)*x30 + qn1_r(3, 3)*x8 + &
               qn2_rr(1, 1, 3)*x3 + qn2_rr(1, 3, 3)*x4
            f4_rrr_rA(1, 1, 3, 3) = t_f4_rrr_rA_0022
            f4_rrr_rA(1, 3, 1, 3) = t_f4_rrr_rA_0022
            f4_rrr_rA(3, 1, 1, 3) = t_f4_rrr_rA_0022
            t_f4_rrr_rA_0110 = &
               -inv_pd*qn3_rrr(1, 2, 2, 1) + qn0(1)*x37 + qn1_r(1, 1)*x14 + qn1_r(2, 1)*x28 + &
               qn2_rr(1, 2, 1)*x12 + qn2_rr(2, 2, 1)*x1
            f4_rrr_rA(1, 2, 2, 1) = t_f4_rrr_rA_0110
            f4_rrr_rA(2, 1, 2, 1) = t_f4_rrr_rA_0110
            f4_rrr_rA(2, 2, 1, 1) = t_f4_rrr_rA_0110
            t_f4_rrr_rA_0111 = &
               -inv_pd*qn3_rrr(1, 2, 2, 2) + qn0(2)*x37 + qn1_r(1, 2)*x14 + qn1_r(2, 2)*x28 + &
               qn2_rr(1, 2, 2)*x12 + qn2_rr(2, 2, 2)*x1
            f4_rrr_rA(1, 2, 2, 2) = t_f4_rrr_rA_0111
            f4_rrr_rA(2, 1, 2, 2) = t_f4_rrr_rA_0111
            f4_rrr_rA(2, 2, 1, 2) = t_f4_rrr_rA_0111
            t_f4_rrr_rA_0112 = &
               -inv_pd*qn3_rrr(1, 2, 2, 3) + qn0(3)*x37 + qn1_r(1, 3)*x14 + qn1_r(2, 3)*x28 + &
               qn2_rr(1, 2, 3)*x12 + qn2_rr(2, 2, 3)*x1
            f4_rrr_rA(1, 2, 2, 3) = t_f4_rrr_rA_0112
            f4_rrr_rA(2, 1, 2, 3) = t_f4_rrr_rA_0112
            f4_rrr_rA(2, 2, 1, 3) = t_f4_rrr_rA_0112
            t_f4_rrr_rA_0120 = &
               -inv_pd*qn3_rrr(1, 2, 3, 1) + qn0(1)*x40 + qn1_r(1, 1)*x16 + qn1_r(2, 1)*x11 + &
               qn1_r(3, 1)*x10 + qn2_rr(1, 2, 1)*x3 + qn2_rr(1, 3, 1)*x2 + qn2_rr(2, 3, 1)*x1
            f4_rrr_rA(1, 2, 3, 1) = t_f4_rrr_rA_0120
            f4_rrr_rA(1, 3, 2, 1) = t_f4_rrr_rA_0120
            f4_rrr_rA(2, 1, 3, 1) = t_f4_rrr_rA_0120
            f4_rrr_rA(2, 3, 1, 1) = t_f4_rrr_rA_0120
            f4_rrr_rA(3, 1, 2, 1) = t_f4_rrr_rA_0120
            f4_rrr_rA(3, 2, 1, 1) = t_f4_rrr_rA_0120
            t_f4_rrr_rA_0121 = &
               -inv_pd*qn3_rrr(1, 2, 3, 2) + qn0(2)*x40 + qn1_r(1, 2)*x16 + qn1_r(2, 2)*x11 + &
               qn1_r(3, 2)*x10 + qn2_rr(1, 2, 2)*x3 + qn2_rr(1, 3, 2)*x2 + qn2_rr(2, 3, 2)*x1
            f4_rrr_rA(1, 2, 3, 2) = t_f4_rrr_rA_0121
            f4_rrr_rA(1, 3, 2, 2) = t_f4_rrr_rA_0121
            f4_rrr_rA(2, 1, 3, 2) = t_f4_rrr_rA_0121
            f4_rrr_rA(2, 3, 1, 2) = t_f4_rrr_rA_0121
            f4_rrr_rA(3, 1, 2, 2) = t_f4_rrr_rA_0121
            f4_rrr_rA(3, 2, 1, 2) = t_f4_rrr_rA_0121
            t_f4_rrr_rA_0122 = &
               -inv_pd*qn3_rrr(1, 2, 3, 3) + qn0(3)*x40 + qn1_r(1, 3)*x16 + qn1_r(2, 3)*x11 + &
               qn1_r(3, 3)*x10 + qn2_rr(1, 2, 3)*x3 + qn2_rr(1, 3, 3)*x2 + qn2_rr(2, 3, 3)*x1
            f4_rrr_rA(1, 2, 3, 3) = t_f4_rrr_rA_0122
            f4_rrr_rA(1, 3, 2, 3) = t_f4_rrr_rA_0122
            f4_rrr_rA(2, 1, 3, 3) = t_f4_rrr_rA_0122
            f4_rrr_rA(2, 3, 1, 3) = t_f4_rrr_rA_0122
            f4_rrr_rA(3, 1, 2, 3) = t_f4_rrr_rA_0122
            f4_rrr_rA(3, 2, 1, 3) = t_f4_rrr_rA_0122
            t_f4_rrr_rA_0220 = &
               -inv_pd*qn3_rrr(1, 3, 3, 1) + qn0(1)*x42 + qn1_r(1, 1)*x19 + qn1_r(3, 1)*x30 + &
               qn2_rr(1, 3, 1)*x17 + qn2_rr(3, 3, 1)*x1
            f4_rrr_rA(1, 3, 3, 1) = t_f4_rrr_rA_0220
            f4_rrr_rA(3, 1, 3, 1) = t_f4_rrr_rA_0220
            f4_rrr_rA(3, 3, 1, 1) = t_f4_rrr_rA_0220
            t_f4_rrr_rA_0221 = &
               -inv_pd*qn3_rrr(1, 3, 3, 2) + qn0(2)*x42 + qn1_r(1, 2)*x19 + qn1_r(3, 2)*x30 + &
               qn2_rr(1, 3, 2)*x17 + qn2_rr(3, 3, 2)*x1
            f4_rrr_rA(1, 3, 3, 2) = t_f4_rrr_rA_0221
            f4_rrr_rA(3, 1, 3, 2) = t_f4_rrr_rA_0221
            f4_rrr_rA(3, 3, 1, 2) = t_f4_rrr_rA_0221
            t_f4_rrr_rA_0222 = &
               -inv_pd*qn3_rrr(1, 3, 3, 3) + qn0(3)*x42 + qn1_r(1, 3)*x19 + qn1_r(3, 3)*x30 + &
               qn2_rr(1, 3, 3)*x17 + qn2_rr(3, 3, 3)*x1
            f4_rrr_rA(1, 3, 3, 3) = t_f4_rrr_rA_0222
            f4_rrr_rA(3, 1, 3, 3) = t_f4_rrr_rA_0222
            f4_rrr_rA(3, 3, 1, 3) = t_f4_rrr_rA_0222
            f4_rrr_rA(2, 2, 2, 1) = &
               -inv_pd*qn3_rrr(2, 2, 2, 1) + qn0(1)*x48 + qn1_r(2, 1)*x45 + qn2_rr(2, 2, 1)*x43
            f4_rrr_rA(2, 2, 2, 2) = &
               -inv_pd*qn3_rrr(2, 2, 2, 2) + qn0(2)*x48 + qn1_r(2, 2)*x45 + qn2_rr(2, 2, 2)*x43
            f4_rrr_rA(2, 2, 2, 3) = &
               -inv_pd*qn3_rrr(2, 2, 2, 3) + qn0(3)*x48 + qn1_r(2, 3)*x45 + qn2_rr(2, 2, 3)*x43
            t_f4_rrr_rA_1120 = &
               -inv_pd*qn3_rrr(2, 2, 3, 1) + qn0(1)*x50 + qn1_r(2, 1)*x49 + qn1_r(3, 1)*x14 + &
               qn2_rr(2, 2, 1)*x3 + qn2_rr(2, 3, 1)*x12
            f4_rrr_rA(2, 2, 3, 1) = t_f4_rrr_rA_1120
            f4_rrr_rA(2, 3, 2, 1) = t_f4_rrr_rA_1120
            f4_rrr_rA(3, 2, 2, 1) = t_f4_rrr_rA_1120
            t_f4_rrr_rA_1121 = &
               -inv_pd*qn3_rrr(2, 2, 3, 2) + qn0(2)*x50 + qn1_r(2, 2)*x49 + qn1_r(3, 2)*x14 + &
               qn2_rr(2, 2, 2)*x3 + qn2_rr(2, 3, 2)*x12
            f4_rrr_rA(2, 2, 3, 2) = t_f4_rrr_rA_1121
            f4_rrr_rA(2, 3, 2, 2) = t_f4_rrr_rA_1121
            f4_rrr_rA(3, 2, 2, 2) = t_f4_rrr_rA_1121
            t_f4_rrr_rA_1122 = &
               -inv_pd*qn3_rrr(2, 2, 3, 3) + qn0(3)*x50 + qn1_r(2, 3)*x49 + qn1_r(3, 3)*x14 + &
               qn2_rr(2, 2, 3)*x3 + qn2_rr(2, 3, 3)*x12
            f4_rrr_rA(2, 2, 3, 3) = t_f4_rrr_rA_1122
            f4_rrr_rA(2, 3, 2, 3) = t_f4_rrr_rA_1122
            f4_rrr_rA(3, 2, 2, 3) = t_f4_rrr_rA_1122
            t_f4_rrr_rA_1220 = &
               -inv_pd*qn3_rrr(2, 3, 3, 1) + qn0(1)*x51 + qn1_r(2, 1)*x19 + qn1_r(3, 1)*x49 + &
               qn2_rr(2, 3, 1)*x17 + qn2_rr(3, 3, 1)*x2
            f4_rrr_rA(2, 3, 3, 1) = t_f4_rrr_rA_1220
            f4_rrr_rA(3, 2, 3, 1) = t_f4_rrr_rA_1220
            f4_rrr_rA(3, 3, 2, 1) = t_f4_rrr_rA_1220
            t_f4_rrr_rA_1221 = &
               -inv_pd*qn3_rrr(2, 3, 3, 2) + qn0(2)*x51 + qn1_r(2, 2)*x19 + qn1_r(3, 2)*x49 + &
               qn2_rr(2, 3, 2)*x17 + qn2_rr(3, 3, 2)*x2
            f4_rrr_rA(2, 3, 3, 2) = t_f4_rrr_rA_1221
            f4_rrr_rA(3, 2, 3, 2) = t_f4_rrr_rA_1221
            f4_rrr_rA(3, 3, 2, 2) = t_f4_rrr_rA_1221
            t_f4_rrr_rA_1222 = &
               -inv_pd*qn3_rrr(2, 3, 3, 3) + qn0(3)*x51 + qn1_r(2, 3)*x19 + qn1_r(3, 3)*x49 + &
               qn2_rr(2, 3, 3)*x17 + qn2_rr(3, 3, 3)*x2
            f4_rrr_rA(2, 3, 3, 3) = t_f4_rrr_rA_1222
            f4_rrr_rA(3, 2, 3, 3) = t_f4_rrr_rA_1222
            f4_rrr_rA(3, 3, 2, 3) = t_f4_rrr_rA_1222
            f4_rrr_rA(3, 3, 3, 1) = &
               -inv_pd*qn3_rrr(3, 3, 3, 1) + qn0(1)*x55 + qn1_r(3, 1)*x54 + qn2_rr(3, 3, 1)*x52
            f4_rrr_rA(3, 3, 3, 2) = &
               -inv_pd*qn3_rrr(3, 3, 3, 2) + qn0(2)*x55 + qn1_r(3, 2)*x54 + qn2_rr(3, 3, 2)*x52
            f4_rrr_rA(3, 3, 3, 3) = &
               -inv_pd*qn3_rrr(3, 3, 3, 3) + qn0(3)*x55 + qn1_r(3, 3)*x54 + qn2_rr(3, 3, 3)*x52
         end block
      end select

   end subroutine cfc_nuclear_eval

   !> Lift the accumulated tensors to the uncontracted level-set nuclear Hessian.
   !>
   !> With ``S = -log PD`` and two retained nuclei A and B,
   !>
   !>    f{k+2}_..._rArB(i1..ik, beta, gamma) = d2/(dR_A,beta dR_B,gamma)
   !>                                           d^k S / dr_i1..dr_ik
   !>
   !> Four accumulated families feed it.  `pd*` is the aggregate; `qa*` and
   !> `qb*` are the per-atom nuclear derivatives of A and of B (both from
   !> `*_nuclear_eval`, just evaluated for different atoms); `qq*` is the
   !> two-nucleus family of `*_hessian_eval` for this particular pair.
   !>
   !> Call once per ordered atom pair per evaluation point, i.e. O(n_active**2)
   !> in total -- which is the size of the result, not an avoidable cost.  A
   !> caller that only needs the Hessian contracted against a displacement
   !> field should use `cfc_hvp_eval` instead and stay O(n_active).
   !>
   !> @param[in]    pd0        Accumulated order-0 spatial derivative of PD
   !> @param[in]    pd1_r      Accumulated order-1 spatial derivative of PD
   !> @param[in]    pd2_rr     Accumulated order-2 spatial derivative of PD
   !> @param[in]    qa0        Atom-A d/dR_A of the order-0 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    qa1_r      Atom-A d/dR_A of the order-1 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    qa2_rr     Atom-A d/dR_A of the order-2 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    qb0        Atom-B d/dR_B of the order-0 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    qb1_r      Atom-B d/dR_B of the order-1 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    qb2_rr     Atom-B d/dR_B of the order-2 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    qq0        d2/(dR_A dR_B) of the order-0 spatial derivative of PD; the two
   !>                          trailing indices are the nuclear components of A and B
   !> @param[in]    qq1_r      d2/(dR_A dR_B) of the order-1 spatial derivative of PD; the two
   !>                          trailing indices are the nuclear components of A and B
   !> @param[in]    qq2_rr     d2/(dR_A dR_B) of the order-2 spatial derivative of PD; the two
   !>                          trailing indices are the nuclear components of A and B
   !> @param[in]    max_deriv  Highest spatial-derivative order to lift (0..2); a larger value is
   !>                          treated as 2
   !> @param[out]   f2_rArB    d2/(dR_A dR_B) of the order-0 spatial derivative of the level set;
   !>                          the two trailing indices are the nuclear components of A and B
   !> @param[out]   f3_r_rArB  d2/(dR_A dR_B) of the order-1 spatial derivative of the level set;
   !>                          the two trailing indices are the nuclear components of A and B
   !> @param[out]   f4_rr_rArB d2/(dR_A dR_B) of the order-2 spatial derivative of the level set;
   !>                          the two trailing indices are the nuclear components of A and B
   pure subroutine cfc_hessian_eval(pd0, pd1_r, pd2_rr, qa0, qa1_r, qa2_rr, qb0, qb1_r, qb2_rr, &
                                    qq0, qq1_r, qq2_rr, max_deriv, f2_rArB, f3_r_rArB, f4_rr_rArB)
      !> Accumulated order-0 spatial derivative of PD
      real(wp), intent(in) :: pd0
      !> Accumulated order-1 spatial derivative of PD
      real(wp), intent(in) :: pd1_r(3)
      !> Accumulated order-2 spatial derivative of PD
      real(wp), intent(in) :: pd2_rr(3, 3)
      !> Atom-A d/dR_A of the order-0 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qa0(3)
      !> Atom-A d/dR_A of the order-1 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qa1_r(3, 3)
      !> Atom-A d/dR_A of the order-2 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qa2_rr(3, 3, 3)
      !> Atom-B d/dR_B of the order-0 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qb0(3)
      !> Atom-B d/dR_B of the order-1 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qb1_r(3, 3)
      !> Atom-B d/dR_B of the order-2 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qb2_rr(3, 3, 3)
      !> d2/(dR_A dR_B) of the order-0 spatial derivative of PD; the two trailing indices are the
      !> nuclear components of A and B
      real(wp), intent(in) :: qq0(3, 3)
      !> d2/(dR_A dR_B) of the order-1 spatial derivative of PD; the two trailing indices are the
      !> nuclear components of A and B
      real(wp), intent(in) :: qq1_r(3, 3, 3)
      !> d2/(dR_A dR_B) of the order-2 spatial derivative of PD; the two trailing indices are the
      !> nuclear components of A and B
      real(wp), intent(in) :: qq2_rr(3, 3, 3, 3)
      !> Highest spatial-derivative order to lift (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d2/(dR_A dR_B) of the order-0 spatial derivative of the level set; the two trailing indices
      !> are the nuclear components of A and B
