               qq0(1, 3)*x65 + qq1_r(3, 1, 3)*x61
            f4_rr_rArB(3, 3, 2, 1) = &
               -inv_pd*qq2_rr(3, 3, 2, 1) + qb0(1)*x69 + qb1_r(3, 1)*x68 + qb2_rr(3, 3, 1)*x2 + &
               qq0(2, 1)*x65 + qq1_r(3, 2, 1)*x61
            f4_rr_rArB(3, 3, 2, 2) = &
               -inv_pd*qq2_rr(3, 3, 2, 2) + qb0(2)*x69 + qb1_r(3, 2)*x68 + qb2_rr(3, 3, 2)*x2 + &
               qq0(2, 2)*x65 + qq1_r(3, 2, 2)*x61
            f4_rr_rArB(3, 3, 2, 3) = &
               -inv_pd*qq2_rr(3, 3, 2, 3) + qb0(3)*x69 + qb1_r(3, 3)*x68 + qb2_rr(3, 3, 3)*x2 + &
               qq0(2, 3)*x65 + qq1_r(3, 2, 3)*x61
            f4_rr_rArB(3, 3, 3, 1) = &
               -inv_pd*qq2_rr(3, 3, 3, 1) + qb0(1)*x71 + qb1_r(3, 1)*x70 + qb2_rr(3, 3, 1)*x3 + &
               qq0(3, 1)*x65 + qq1_r(3, 3, 1)*x61
            f4_rr_rArB(3, 3, 3, 2) = &
               -inv_pd*qq2_rr(3, 3, 3, 2) + qb0(2)*x71 + qb1_r(3, 2)*x70 + qb2_rr(3, 3, 2)*x3 + &
               qq0(3, 2)*x65 + qq1_r(3, 3, 2)*x61
            f4_rr_rArB(3, 3, 3, 3) = &
               -inv_pd*qq2_rr(3, 3, 3, 3) + qb0(3)*x71 + qb1_r(3, 3)*x70 + qb2_rr(3, 3, 3)*x3 + &
               qq0(3, 3)*x65 + qq1_r(3, 3, 3)*x61
         end block
      end select

   end subroutine cfc_hessian_eval

   !> Lift the accumulated tensors to the level-set directional derivative.
   !>
   !> With ``S = -log PD`` and one displacement direction per atom,
   !>
   !>    tangent_f{k}(i1..ik) = sum_B sum_beta v_B,beta
   !>                           d/dR_B,beta  d^k S / dr_i1..dr_ik
   !>
   !> Both inputs are aggregates: `pd*` from the `*_term_eval` loops and `tg*`
   !> from the `*_tangent_eval` loops, each summed over every atom and pair.
   !> The lift itself is O(1) -- one call per evaluation point.
   !>
   !> This is the SvdW `svdw_tangent_eval` contract, term for term: the caller
   !> receives derivatives of the level set and never applies a chain rule.
   !>
   !> @param[in]    pd0        Accumulated order-0 spatial derivative of PD
   !> @param[in]    pd1_r      Accumulated order-1 spatial derivative of PD
   !> @param[in]    pd2_rr     Accumulated order-2 spatial derivative of PD
   !> @param[in]    pd3_rrr    Accumulated order-3 spatial derivative of PD
   !> @param[in]    tg0        Accumulated sum_B v_B . d/dR_B of the order-0 derivative of PD
   !> @param[in]    tg1_r      Accumulated sum_B v_B . d/dR_B of the order-1 derivative of PD
   !> @param[in]    tg2_rr     Accumulated sum_B v_B . d/dR_B of the order-2 derivative of PD
   !> @param[in]    tg3_rrr    Accumulated sum_B v_B . d/dR_B of the order-3 derivative of PD
   !> @param[in]    max_deriv  Highest spatial-derivative order to lift (0..3); a larger value is
   !>                          treated as 3
   !> @param[out]   tangent_f0 sum_B v_B . d/dR_B of the order-0 spatial derivative of the level set
   !> @param[out]   tangent_f1_r sum_B v_B . d/dR_B of the order-1 spatial derivative of the level
   !>                            set
   !> @param[out]   tangent_f2_rr sum_B v_B . d/dR_B of the order-2 spatial derivative of the level
   !>                             set
   !> @param[out]   tangent_f3_rrr sum_B v_B . d/dR_B of the order-3 spatial derivative of the level
   !>                              set
   pure subroutine cfc_tangent_eval(pd0, pd1_r, pd2_rr, pd3_rrr, tg0, tg1_r, tg2_rr, tg3_rrr, &
                                    max_deriv, tangent_f0, tangent_f1_r, tangent_f2_rr, &
                                    tangent_f3_rrr)
      !> Accumulated order-0 spatial derivative of PD
      real(wp), intent(in) :: pd0
      !> Accumulated order-1 spatial derivative of PD
      real(wp), intent(in) :: pd1_r(3)
      !> Accumulated order-2 spatial derivative of PD
      real(wp), intent(in) :: pd2_rr(3, 3)
      !> Accumulated order-3 spatial derivative of PD
      real(wp), intent(in) :: pd3_rrr(3, 3, 3)
      !> Accumulated sum_B v_B . d/dR_B of the order-0 derivative of PD
      real(wp), intent(in) :: tg0
      !> Accumulated sum_B v_B . d/dR_B of the order-1 derivative of PD
      real(wp), intent(in) :: tg1_r(3)
      !> Accumulated sum_B v_B . d/dR_B of the order-2 derivative of PD
      real(wp), intent(in) :: tg2_rr(3, 3)
      !> Accumulated sum_B v_B . d/dR_B of the order-3 derivative of PD
      real(wp), intent(in) :: tg3_rrr(3, 3, 3)
      !> Highest spatial-derivative order to lift (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> sum_B v_B . d/dR_B of the order-0 spatial derivative of the level set
      real(wp), intent(out) :: tangent_f0
      !> sum_B v_B . d/dR_B of the order-1 spatial derivative of the level set
      real(wp), intent(out) :: tangent_f1_r(3)
      !> sum_B v_B . d/dR_B of the order-2 spatial derivative of the level set
      real(wp), intent(out) :: tangent_f2_rr(3, 3)
      !> sum_B v_B . d/dR_B of the order-3 spatial derivative of the level set
      real(wp), intent(out) :: tangent_f3_rrr(3, 3, 3)

      !> Reciprocal of the total pseudo-density
      real(wp) :: inv_pd

      ! Unconditional: the max_deriv dispatch below writes only the orders it
      ! was asked for, so every higher-order result must already be defined.
      tangent_f0 = 0.0_wp
      tangent_f1_r = 0.0_wp
      tangent_f2_rr = 0.0_wp
      tangent_f3_rrr = 0.0_wp

      if (pd0 <= 0.0_wp) return
      inv_pd = 1.0_wp/pd0

      select case (max_deriv)
      case (0)
         block
            tangent_f0 = -inv_pd*tg0
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0

            x0 = (inv_pd*inv_pd)*tg0
            tangent_f0 = -inv_pd*tg0
            tangent_f1_r(1) = -inv_pd*tg1_r(1) + pd1_r(1)*x0
            tangent_f1_r(2) = -inv_pd*tg1_r(2) + pd1_r(2)*x0
            tangent_f1_r(3) = -inv_pd*tg1_r(3) + pd1_r(3)*x0
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, t_tangent_f2_rr_01, t_tangent_f2_rr_02
            real(wp) :: t_tangent_f2_rr_12

            x0 = (inv_pd*inv_pd)
            x1 = tg0*x0
            x2 = pd1_r(1)*x0
            x3 = 2.0_wp*(inv_pd*inv_pd*inv_pd)
            x4 = tg1_r(1)*x0
            x5 = pd1_r(1)*x3
            x6 = pd1_r(2)*x0
            x7 = pd1_r(3)*x0
            tangent_f0 = -inv_pd*tg0
            tangent_f1_r(1) = -inv_pd*tg1_r(1) + pd1_r(1)*x1
            tangent_f1_r(2) = -inv_pd*tg1_r(2) + pd1_r(2)*x1
            tangent_f1_r(3) = -inv_pd*tg1_r(3) + pd1_r(3)*x1
            tangent_f2_rr(1, 1) = &
               -inv_pd*tg2_rr(1, 1) + tg0*(-(pd1_r(1)*pd1_r(1))*x3 + pd2_rr(1, 1)*x0) + &
               2.0_wp*tg1_r(1)*x2
            t_tangent_f2_rr_01 = &
               -inv_pd*tg2_rr(1, 2) + pd1_r(2)*x4 + tg0*(-pd1_r(2)*x5 + pd2_rr(1, 2)*x0) + &
               tg1_r(2)*x2
            tangent_f2_rr(1, 2) = t_tangent_f2_rr_01
            tangent_f2_rr(2, 1) = t_tangent_f2_rr_01
            t_tangent_f2_rr_02 = &
               -inv_pd*tg2_rr(1, 3) + pd1_r(3)*x4 + tg0*(-pd1_r(3)*x5 + pd2_rr(1, 3)*x0) + &
               tg1_r(3)*x2
            tangent_f2_rr(1, 3) = t_tangent_f2_rr_02
            tangent_f2_rr(3, 1) = t_tangent_f2_rr_02
            tangent_f2_rr(2, 2) = &
               -inv_pd*tg2_rr(2, 2) + tg0*(-(pd1_r(2)*pd1_r(2))*x3 + pd2_rr(2, 2)*x0) + &
               2.0_wp*tg1_r(2)*x6
            t_tangent_f2_rr_12 = &
               -inv_pd*tg2_rr(2, 3) + tg0*(-pd1_r(2)*pd1_r(3)*x3 + pd2_rr(2, 3)*x0) + tg1_r(2)*x7 &
               + tg1_r(3)*x6
            tangent_f2_rr(2, 3) = t_tangent_f2_rr_12
            tangent_f2_rr(3, 2) = t_tangent_f2_rr_12
            tangent_f2_rr(3, 3) = &
               -inv_pd*tg2_rr(3, 3) + tg0*(-(pd1_r(3)*pd1_r(3))*x3 + pd2_rr(3, 3)*x0) + &
               2.0_wp*tg1_r(3)*x7
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, t_tangent_f2_rr_01
            real(wp) :: t_tangent_f2_rr_02, t_tangent_f2_rr_12, t_tangent_f3_rrr_001
            real(wp) :: t_tangent_f3_rrr_002, t_tangent_f3_rrr_011, t_tangent_f3_rrr_012
            real(wp) :: t_tangent_f3_rrr_022, t_tangent_f3_rrr_112, t_tangent_f3_rrr_122

            x0 = (inv_pd*inv_pd)
            x1 = tg0*x0
            x2 = pd1_r(1)*x0
            x3 = 2.0_wp*x2
            x4 = (pd1_r(1)*pd1_r(1))
            x5 = (inv_pd*inv_pd*inv_pd)
            x6 = 2.0_wp*x5
            x7 = pd2_rr(1, 1)*x0 - x4*x6
            x8 = tg1_r(1)*x0
            x9 = pd1_r(1)*x6
            x10 = -pd1_r(2)*x9 + pd2_rr(1, 2)*x0
            x11 = -pd1_r(3)*x9 + pd2_rr(1, 3)*x0
            x12 = pd1_r(2)*x0
            x13 = 2.0_wp*x12
            x14 = (pd1_r(2)*pd1_r(2))
            x15 = pd2_rr(2, 2)*x0 - x14*x6
            x16 = pd1_r(3)*x0
            x17 = pd1_r(2)*pd1_r(3)
            x18 = pd2_rr(2, 3)*x0 - x17*x6
            x19 = 2.0_wp*x16
            x20 = (pd1_r(3)*pd1_r(3))
            x21 = pd2_rr(3, 3)*x0 - x20*x6
            x22 = 6.0_wp*x4
            x23 = 4.0_wp*x5
            x24 = pd1_r(1)*x23
            x25 = (inv_pd*inv_pd*inv_pd*inv_pd)
            x26 = -pd2_rr(1, 1)*x6 + x22*x25
            x27 = -pd1_r(2)*x24 + 2.0_wp*pd2_rr(1, 2)*x0
            x28 = -pd1_r(3)*x24 + 2.0_wp*pd2_rr(1, 3)*x0
            x29 = pd2_rr(2, 2)*x6
            x30 = pd2_rr(1, 2)*x6
            x31 = 6.0_wp*x25
            x32 = pd1_r(1)*x31
            x33 = pd1_r(2)*x32 - x30
            x34 = pd2_rr(2, 3)*x6
            x35 = pd2_rr(1, 3)*x6
            x36 = pd2_rr(3, 3)*x6
            x37 = 6.0_wp*x14
            x38 = pd1_r(2)*x23
            x39 = x25*x37 - x29
            x40 = 2.0_wp*pd2_rr(2, 3)*x0 - x17*x23
            x41 = 6.0_wp*x20
            tangent_f0 = -inv_pd*tg0
            tangent_f1_r(1) = -inv_pd*tg1_r(1) + pd1_r(1)*x1
            tangent_f1_r(2) = -inv_pd*tg1_r(2) + pd1_r(2)*x1
            tangent_f1_r(3) = -inv_pd*tg1_r(3) + pd1_r(3)*x1
            tangent_f2_rr(1, 1) = -inv_pd*tg2_rr(1, 1) + tg0*x7 + tg1_r(1)*x3
            t_tangent_f2_rr_01 = -inv_pd*tg2_rr(1, 2) + pd1_r(2)*x8 + tg0*x10 + tg1_r(2)*x2
            tangent_f2_rr(1, 2) = t_tangent_f2_rr_01
            tangent_f2_rr(2, 1) = t_tangent_f2_rr_01
            t_tangent_f2_rr_02 = -inv_pd*tg2_rr(1, 3) + pd1_r(3)*x8 + tg0*x11 + tg1_r(3)*x2
            tangent_f2_rr(1, 3) = t_tangent_f2_rr_02
            tangent_f2_rr(3, 1) = t_tangent_f2_rr_02
            tangent_f2_rr(2, 2) = -inv_pd*tg2_rr(2, 2) + tg0*x15 + tg1_r(2)*x13
            t_tangent_f2_rr_12 = -inv_pd*tg2_rr(2, 3) + tg0*x18 + tg1_r(2)*x16 + tg1_r(3)*x12
            tangent_f2_rr(2, 3) = t_tangent_f2_rr_12
            tangent_f2_rr(3, 2) = t_tangent_f2_rr_12
            tangent_f2_rr(3, 3) = -inv_pd*tg2_rr(3, 3) + tg0*x21 + tg1_r(3)*x19
            tangent_f3_rrr(1, 1, 1) = &
               -inv_pd*tg3_rrr(1, 1, 1) + tg0*(pd1_r(1)*x26 - pd2_rr(1, 1)*x24 + pd3_rrr(1, 1, &
               1)*x0) + tg1_r(1)*(3.0_wp*pd2_rr(1, 1)*x0 - x22*x5) + 3.0_wp*tg2_rr(1, 1)*x2
            t_tangent_f3_rrr_001 = &
               -inv_pd*tg3_rrr(1, 1, 2) + tg0*(pd1_r(2)*x26 - pd2_rr(1, 2)*x24 + pd3_rrr(1, 1, &
               2)*x0) + tg1_r(1)*x27 + tg1_r(2)*x7 + tg2_rr(1, 1)*x12 + tg2_rr(1, 2)*x3
            tangent_f3_rrr(1, 1, 2) = t_tangent_f3_rrr_001
            tangent_f3_rrr(1, 2, 1) = t_tangent_f3_rrr_001
            tangent_f3_rrr(2, 1, 1) = t_tangent_f3_rrr_001
            t_tangent_f3_rrr_002 = &
               -inv_pd*tg3_rrr(1, 1, 3) + tg0*(pd1_r(3)*x26 - pd2_rr(1, 3)*x24 + pd3_rrr(1, 1, &
               3)*x0) + tg1_r(1)*x28 + tg1_r(3)*x7 + tg2_rr(1, 1)*x16 + tg2_rr(1, 3)*x3
            tangent_f3_rrr(1, 1, 3) = t_tangent_f3_rrr_002
            tangent_f3_rrr(1, 3, 1) = t_tangent_f3_rrr_002
            tangent_f3_rrr(3, 1, 1) = t_tangent_f3_rrr_002
            t_tangent_f3_rrr_011 = &
               -inv_pd*tg3_rrr(1, 2, 2) + tg0*(-pd1_r(1)*x29 - pd1_r(2)*x30 + pd1_r(2)*x33 + &
               pd3_rrr(1, 2, 2)*x0) + tg1_r(1)*x15 + tg1_r(2)*x27 + tg2_rr(1, 2)*x13 + tg2_rr(2, &
               2)*x2
            tangent_f3_rrr(1, 2, 2) = t_tangent_f3_rrr_011
            tangent_f3_rrr(2, 1, 2) = t_tangent_f3_rrr_011
            tangent_f3_rrr(2, 2, 1) = t_tangent_f3_rrr_011
            t_tangent_f3_rrr_012 = &
               -inv_pd*tg3_rrr(1, 2, 3) + tg0*(-pd1_r(1)*x34 - pd1_r(2)*x35 + pd1_r(3)*x33 + &
               pd3_rrr(1, 2, 3)*x0) + tg1_r(1)*x18 + tg1_r(2)*x11 + tg1_r(3)*x10 + tg2_rr(1, &
               2)*x16 + tg2_rr(1, 3)*x12 + tg2_rr(2, 3)*x2
            tangent_f3_rrr(1, 2, 3) = t_tangent_f3_rrr_012
            tangent_f3_rrr(1, 3, 2) = t_tangent_f3_rrr_012
            tangent_f3_rrr(2, 1, 3) = t_tangent_f3_rrr_012
            tangent_f3_rrr(2, 3, 1) = t_tangent_f3_rrr_012
            tangent_f3_rrr(3, 1, 2) = t_tangent_f3_rrr_012
            tangent_f3_rrr(3, 2, 1) = t_tangent_f3_rrr_012
            t_tangent_f3_rrr_022 = &
               -inv_pd*tg3_rrr(1, 3, 3) + tg0*(-pd1_r(1)*x36 - pd1_r(3)*x35 + &
               pd1_r(3)*(pd1_r(3)*x32 - x35) + pd3_rrr(1, 3, 3)*x0) + tg1_r(1)*x21 + tg1_r(3)*x28 &
               + tg2_rr(1, 3)*x19 + tg2_rr(3, 3)*x2
            tangent_f3_rrr(1, 3, 3) = t_tangent_f3_rrr_022
            tangent_f3_rrr(3, 1, 3) = t_tangent_f3_rrr_022
            tangent_f3_rrr(3, 3, 1) = t_tangent_f3_rrr_022
            tangent_f3_rrr(2, 2, 2) = &
               -inv_pd*tg3_rrr(2, 2, 2) + tg0*(pd1_r(2)*x39 - pd2_rr(2, 2)*x38 + pd3_rrr(2, 2, &
               2)*x0) + tg1_r(2)*(3.0_wp*pd2_rr(2, 2)*x0 - x37*x5) + 3.0_wp*tg2_rr(2, 2)*x12
            t_tangent_f3_rrr_112 = &
               -inv_pd*tg3_rrr(2, 2, 3) + tg0*(pd1_r(3)*x39 - pd2_rr(2, 3)*x38 + pd3_rrr(2, 2, &
               3)*x0) + tg1_r(2)*x40 + tg1_r(3)*x15 + tg2_rr(2, 2)*x16 + tg2_rr(2, 3)*x13
            tangent_f3_rrr(2, 2, 3) = t_tangent_f3_rrr_112
            tangent_f3_rrr(2, 3, 2) = t_tangent_f3_rrr_112
            tangent_f3_rrr(3, 2, 2) = t_tangent_f3_rrr_112
            t_tangent_f3_rrr_122 = &
               -inv_pd*tg3_rrr(2, 3, 3) + tg0*(-pd1_r(2)*x36 - pd1_r(3)*x34 + pd1_r(3)*(x17*x31 - &
               x34) + pd3_rrr(2, 3, 3)*x0) + tg1_r(2)*x21 + tg1_r(3)*x40 + tg2_rr(2, 3)*x19 + &
               tg2_rr(3, 3)*x12
            tangent_f3_rrr(2, 3, 3) = t_tangent_f3_rrr_122
            tangent_f3_rrr(3, 2, 3) = t_tangent_f3_rrr_122
            tangent_f3_rrr(3, 3, 2) = t_tangent_f3_rrr_122
            tangent_f3_rrr(3, 3, 3) = &
               -inv_pd*tg3_rrr(3, 3, 3) + tg0*(-pd1_r(3)*pd2_rr(3, 3)*x23 + pd1_r(3)*(x25*x41 - &
               x36) + pd3_rrr(3, 3, 3)*x0) + tg1_r(3)*(3.0_wp*pd2_rr(3, 3)*x0 - x41*x5) + &
               3.0_wp*tg2_rr(3, 3)*x16
         end block
      end select

   end subroutine cfc_tangent_eval

   !> Lift the accumulated tensors to the level-set Hessian-vector product.
   !>
   !> With ``S = -log PD``, one displacement direction per atom and one retained
   !> nucleus A,
   !>
   !>    hvp_f{k+1}_..._rA(i1..ik, beta) = sum_B sum_gamma v_B,gamma
   !>                                      d^2/(dR_A,beta dR_B,gamma)
   !>                                      d^k S / dr_i1..dr_ik
   !>
   !> Four accumulated families feed it.  Two are aggregates, summed over all
   !> atoms and pairs: `pd*` (`*_term_eval`) and `tg*` (`*_tangent_eval`).  Two
   !> are per-atom, summed over atom A's own term and every pair containing A:
   !> `qn*` (`*_nuclear_eval`) and `hvp*` (`*_hvp_eval`).  Nothing here is
   !> O(n**2) in storage; the pairwise nuclear Hessian is never formed.
   !>
   !> Call once per atom A per evaluation point, i.e. O(n_active) in total.
   !>
   !> @param[in]    pd0        Accumulated order-0 spatial derivative of PD
   !> @param[in]    pd1_r      Accumulated order-1 spatial derivative of PD
   !> @param[in]    pd2_rr     Accumulated order-2 spatial derivative of PD
   !> @param[in]    tg0        Accumulated sum_B v_B . d/dR_B of the order-0 derivative of PD
   !> @param[in]    tg1_r      Accumulated sum_B v_B . d/dR_B of the order-1 derivative of PD
   !> @param[in]    tg2_rr     Accumulated sum_B v_B . d/dR_B of the order-2 derivative of PD
   !> @param[in]    qn0        Atom-A d/dR_A of the order-0 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    qn1_r      Atom-A d/dR_A of the order-1 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    qn2_rr     Atom-A d/dR_A of the order-2 spatial derivative of PD; trailing index
   !>                          is the nuclear component
   !> @param[in]    hvp0       Atom-A sum_B v_B . d2/(dR_A dR_B) of the order-0 spatial derivative
   !>                          of PD; trailing index is the retained nuclear component
   !> @param[in]    hvp1_r     Atom-A sum_B v_B . d2/(dR_A dR_B) of the order-1 spatial derivative
   !>                          of PD; trailing index is the retained nuclear component
   !> @param[in]    hvp2_rr    Atom-A sum_B v_B . d2/(dR_A dR_B) of the order-2 spatial derivative
   !>                          of PD; trailing index is the retained nuclear component
   !> @param[in]    max_deriv  Highest spatial-derivative order to lift (0..2); a larger value is
   !>                          treated as 2
   !> @param[out]   hvp_f1_rA  sum_B v_B . d2/(dR_A dR_B) of the order-0 spatial derivative of the
   !>                          level set; trailing index is the retained nuclear component
   !> @param[out]   hvp_f2_r_rA sum_B v_B . d2/(dR_A dR_B) of the order-1 spatial derivative of the
   !>                           level set; trailing index is the retained nuclear component
   !> @param[out]   hvp_f3_rr_rA sum_B v_B . d2/(dR_A dR_B) of the order-2 spatial derivative of the
   !>                            level set; trailing index is the retained nuclear component
   pure subroutine cfc_hvp_eval(pd0, pd1_r, pd2_rr, tg0, tg1_r, tg2_rr, qn0, qn1_r, qn2_rr, hvp0, &
                                hvp1_r, hvp2_rr, max_deriv, hvp_f1_rA, hvp_f2_r_rA, hvp_f3_rr_rA)
      !> Accumulated order-0 spatial derivative of PD
      real(wp), intent(in) :: pd0
      !> Accumulated order-1 spatial derivative of PD
      real(wp), intent(in) :: pd1_r(3)
      !> Accumulated order-2 spatial derivative of PD
      real(wp), intent(in) :: pd2_rr(3, 3)
      !> Accumulated sum_B v_B . d/dR_B of the order-0 derivative of PD
      real(wp), intent(in) :: tg0
      !> Accumulated sum_B v_B . d/dR_B of the order-1 derivative of PD
      real(wp), intent(in) :: tg1_r(3)
      !> Accumulated sum_B v_B . d/dR_B of the order-2 derivative of PD
      real(wp), intent(in) :: tg2_rr(3, 3)
      !> Atom-A d/dR_A of the order-0 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn0(3)
      !> Atom-A d/dR_A of the order-1 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn1_r(3, 3)
      !> Atom-A d/dR_A of the order-2 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn2_rr(3, 3, 3)
      !> Atom-A sum_B v_B . d2/(dR_A dR_B) of the order-0 spatial derivative of PD; trailing index
      !> is the retained nuclear component
      real(wp), intent(in) :: hvp0(3)
      !> Atom-A sum_B v_B . d2/(dR_A dR_B) of the order-1 spatial derivative of PD; trailing index
      !> is the retained nuclear component
      real(wp), intent(in) :: hvp1_r(3, 3)
      !> Atom-A sum_B v_B . d2/(dR_A dR_B) of the order-2 spatial derivative of PD; trailing index
      !> is the retained nuclear component
      real(wp), intent(in) :: hvp2_rr(3, 3, 3)
      !> Highest spatial-derivative order to lift (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> sum_B v_B . d2/(dR_A dR_B) of the order-0 spatial derivative of the level set; trailing
      !> index is the retained nuclear component
      real(wp), intent(out) :: hvp_f1_rA(3)
      !> sum_B v_B . d2/(dR_A dR_B) of the order-1 spatial derivative of the level set; trailing
      !> index is the retained nuclear component
      real(wp), intent(out) :: hvp_f2_r_rA(3, 3)
      !> sum_B v_B . d2/(dR_A dR_B) of the order-2 spatial derivative of the level set; trailing
      !> index is the retained nuclear component
      real(wp), intent(out) :: hvp_f3_rr_rA(3, 3, 3)

      !> Reciprocal of the total pseudo-density
      real(wp) :: inv_pd

      ! Unconditional: the max_deriv dispatch below writes only the orders it
      ! was asked for, so every higher-order result must already be defined.
      hvp_f1_rA = 0.0_wp
      hvp_f2_r_rA = 0.0_wp
      hvp_f3_rr_rA = 0.0_wp

      if (pd0 <= 0.0_wp) return
      inv_pd = 1.0_wp/pd0

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0

            x0 = (inv_pd*inv_pd)
            hvp_f1_rA(1) = -hvp0(1)*inv_pd + qn0(1)*tg0*x0
            hvp_f1_rA(2) = -hvp0(2)*inv_pd + qn0(2)*tg0*x0
            hvp_f1_rA(3) = -hvp0(3)*inv_pd + qn0(3)*tg0*x0
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8

            x0 = (inv_pd*inv_pd)
            x1 = pd1_r(1)*x0
            x2 = tg0*x0
            x3 = 2.0_wp*(inv_pd*inv_pd*inv_pd)*tg0
            x4 = -pd1_r(1)*x3 + tg1_r(1)*x0
            x5 = pd1_r(2)*x0
            x6 = -pd1_r(2)*x3 + tg1_r(2)*x0
            x7 = pd1_r(3)*x0
            x8 = -pd1_r(3)*x3 + tg1_r(3)*x0
            hvp_f1_rA(1) = -hvp0(1)*inv_pd + qn0(1)*tg0*x0
            hvp_f1_rA(2) = -hvp0(2)*inv_pd + qn0(2)*tg0*x0
            hvp_f1_rA(3) = -hvp0(3)*inv_pd + qn0(3)*tg0*x0
            hvp_f2_r_rA(1, 1) = hvp0(1)*x1 - hvp1_r(1, 1)*inv_pd + qn0(1)*x4 + qn1_r(1, 1)*x2
            hvp_f2_r_rA(1, 2) = hvp0(2)*x1 - hvp1_r(1, 2)*inv_pd + qn0(2)*x4 + qn1_r(1, 2)*x2
            hvp_f2_r_rA(1, 3) = hvp0(3)*x1 - hvp1_r(1, 3)*inv_pd + qn0(3)*x4 + qn1_r(1, 3)*x2
            hvp_f2_r_rA(2, 1) = hvp0(1)*x5 - hvp1_r(2, 1)*inv_pd + qn0(1)*x6 + qn1_r(2, 1)*x2
            hvp_f2_r_rA(2, 2) = hvp0(2)*x5 - hvp1_r(2, 2)*inv_pd + qn0(2)*x6 + qn1_r(2, 2)*x2
            hvp_f2_r_rA(2, 3) = hvp0(3)*x5 - hvp1_r(2, 3)*inv_pd + qn0(3)*x6 + qn1_r(2, 3)*x2
            hvp_f2_r_rA(3, 1) = hvp0(1)*x7 - hvp1_r(3, 1)*inv_pd + qn0(1)*x8 + qn1_r(3, 1)*x2
            hvp_f2_r_rA(3, 2) = hvp0(2)*x7 - hvp1_r(3, 2)*inv_pd + qn0(2)*x8 + qn1_r(3, 2)*x2
            hvp_f2_r_rA(3, 3) = hvp0(3)*x7 - hvp1_r(3, 3)*inv_pd + qn0(3)*x8 + qn1_r(3, 3)*x2
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, t_hvp_f3_rr_rA_010
            real(wp) :: t_hvp_f3_rr_rA_011, t_hvp_f3_rr_rA_012, t_hvp_f3_rr_rA_020
            real(wp) :: t_hvp_f3_rr_rA_021, t_hvp_f3_rr_rA_022, t_hvp_f3_rr_rA_120
            real(wp) :: t_hvp_f3_rr_rA_121, t_hvp_f3_rr_rA_122

            x0 = (inv_pd*inv_pd)
            x1 = pd1_r(1)*x0
            x2 = tg0*x0
            x3 = (inv_pd*inv_pd*inv_pd)
            x4 = 2.0_wp*x3
            x5 = tg0*x4
            x6 = -pd1_r(1)*x5 + tg1_r(1)*x0
            x7 = pd1_r(2)*x0
            x8 = -pd1_r(2)*x5 + tg1_r(2)*x0
            x9 = pd1_r(3)*x0
            x10 = -pd1_r(3)*x5 + tg1_r(3)*x0
            x11 = 2.0_wp*x1
            x12 = (pd1_r(1)*pd1_r(1))
            x13 = pd2_rr(1, 1)*x0 - x12*x4
            x14 = 4.0_wp*x3
            x15 = pd1_r(1)*x14
            x16 = -tg0*x15 + 2.0_wp*tg1_r(1)*x0
            x17 = 6.0_wp*(inv_pd*inv_pd*inv_pd*inv_pd)
            x18 = tg0*(-pd2_rr(1, 1)*x4 + x12*x17) - tg1_r(1)*x15 + tg2_rr(1, 1)*x0
            x19 = pd1_r(1)*pd1_r(2)
            x20 = pd2_rr(1, 2)*x0 - x19*x4
            x21 = pd1_r(1)*x4
            x22 = tg1_r(1)*x4
            x23 = -pd1_r(2)*x22 + tg0*(-pd2_rr(1, 2)*x4 + x17*x19) - tg1_r(2)*x21 + tg2_rr(1, 2)*x0
            x24 = -pd1_r(3)*x21 + pd2_rr(1, 3)*x0
            x25 = pd1_r(3)*x17
            x26 = &
               -pd1_r(3)*x22 + tg0*(pd1_r(1)*x25 - pd2_rr(1, 3)*x4) - tg1_r(3)*x21 + tg2_rr(1, &
               3)*x0
            x27 = 2.0_wp*x7
            x28 = (pd1_r(2)*pd1_r(2))
            x29 = pd2_rr(2, 2)*x0 - x28*x4
            x30 = pd1_r(2)*x14
            x31 = -tg0*x30 + 2.0_wp*tg1_r(2)*x0
            x32 = tg0*(-pd2_rr(2, 2)*x4 + x17*x28) - tg1_r(2)*x30 + tg2_rr(2, 2)*x0
            x33 = pd1_r(2)*x4
            x34 = -pd1_r(3)*x33 + pd2_rr(2, 3)*x0
            x35 = &
               -pd1_r(3)*tg1_r(2)*x4 + tg0*(pd1_r(2)*x25 - pd2_rr(2, 3)*x4) - tg1_r(3)*x33 + &
               tg2_rr(2, 3)*x0
            x36 = 2.0_wp*x9
            x37 = (pd1_r(3)*pd1_r(3))
            x38 = pd2_rr(3, 3)*x0 - x37*x4
            x39 = pd1_r(3)*x14
            x40 = -tg0*x39 + 2.0_wp*tg1_r(3)*x0
            x41 = tg0*(-pd2_rr(3, 3)*x4 + x17*x37) - tg1_r(3)*x39 + tg2_rr(3, 3)*x0
            hvp_f1_rA(1) = -hvp0(1)*inv_pd + qn0(1)*tg0*x0
            hvp_f1_rA(2) = -hvp0(2)*inv_pd + qn0(2)*tg0*x0
            hvp_f1_rA(3) = -hvp0(3)*inv_pd + qn0(3)*tg0*x0
            hvp_f2_r_rA(1, 1) = hvp0(1)*x1 - hvp1_r(1, 1)*inv_pd + qn0(1)*x6 + qn1_r(1, 1)*x2
            hvp_f2_r_rA(1, 2) = hvp0(2)*x1 - hvp1_r(1, 2)*inv_pd + qn0(2)*x6 + qn1_r(1, 2)*x2
            hvp_f2_r_rA(1, 3) = hvp0(3)*x1 - hvp1_r(1, 3)*inv_pd + qn0(3)*x6 + qn1_r(1, 3)*x2
            hvp_f2_r_rA(2, 1) = hvp0(1)*x7 - hvp1_r(2, 1)*inv_pd + qn0(1)*x8 + qn1_r(2, 1)*x2
            hvp_f2_r_rA(2, 2) = hvp0(2)*x7 - hvp1_r(2, 2)*inv_pd + qn0(2)*x8 + qn1_r(2, 2)*x2
            hvp_f2_r_rA(2, 3) = hvp0(3)*x7 - hvp1_r(2, 3)*inv_pd + qn0(3)*x8 + qn1_r(2, 3)*x2
            hvp_f2_r_rA(3, 1) = hvp0(1)*x9 - hvp1_r(3, 1)*inv_pd + qn0(1)*x10 + qn1_r(3, 1)*x2
            hvp_f2_r_rA(3, 2) = hvp0(2)*x9 - hvp1_r(3, 2)*inv_pd + qn0(2)*x10 + qn1_r(3, 2)*x2
            hvp_f2_r_rA(3, 3) = hvp0(3)*x9 - hvp1_r(3, 3)*inv_pd + qn0(3)*x10 + qn1_r(3, 3)*x2
            hvp_f3_rr_rA(1, 1, 1) = &
               hvp0(1)*x13 + hvp1_r(1, 1)*x11 - hvp2_rr(1, 1, 1)*inv_pd + qn0(1)*x18 + qn1_r(1, &
               1)*x16 + qn2_rr(1, 1, 1)*x2
            hvp_f3_rr_rA(1, 1, 2) = &
               hvp0(2)*x13 + hvp1_r(1, 2)*x11 - hvp2_rr(1, 1, 2)*inv_pd + qn0(2)*x18 + qn1_r(1, &
               2)*x16 + qn2_rr(1, 1, 2)*x2
            hvp_f3_rr_rA(1, 1, 3) = &
               hvp0(3)*x13 + hvp1_r(1, 3)*x11 - hvp2_rr(1, 1, 3)*inv_pd + qn0(3)*x18 + qn1_r(1, &
               3)*x16 + qn2_rr(1, 1, 3)*x2
            t_hvp_f3_rr_rA_010 = &
               hvp0(1)*x20 + hvp1_r(1, 1)*x7 + hvp1_r(2, 1)*x1 - hvp2_rr(1, 2, 1)*inv_pd + &
               qn0(1)*x23 + qn1_r(1, 1)*x8 + qn1_r(2, 1)*x6 + qn2_rr(1, 2, 1)*x2
            hvp_f3_rr_rA(1, 2, 1) = t_hvp_f3_rr_rA_010
            hvp_f3_rr_rA(2, 1, 1) = t_hvp_f3_rr_rA_010
            t_hvp_f3_rr_rA_011 = &
               hvp0(2)*x20 + hvp1_r(1, 2)*x7 + hvp1_r(2, 2)*x1 - hvp2_rr(1, 2, 2)*inv_pd + &
               qn0(2)*x23 + qn1_r(1, 2)*x8 + qn1_r(2, 2)*x6 + qn2_rr(1, 2, 2)*x2
            hvp_f3_rr_rA(1, 2, 2) = t_hvp_f3_rr_rA_011
            hvp_f3_rr_rA(2, 1, 2) = t_hvp_f3_rr_rA_011
            t_hvp_f3_rr_rA_012 = &
               hvp0(3)*x20 + hvp1_r(1, 3)*x7 + hvp1_r(2, 3)*x1 - hvp2_rr(1, 2, 3)*inv_pd + &
               qn0(3)*x23 + qn1_r(1, 3)*x8 + qn1_r(2, 3)*x6 + qn2_rr(1, 2, 3)*x2
            hvp_f3_rr_rA(1, 2, 3) = t_hvp_f3_rr_rA_012
            hvp_f3_rr_rA(2, 1, 3) = t_hvp_f3_rr_rA_012
            t_hvp_f3_rr_rA_020 = &
               hvp0(1)*x24 + hvp1_r(1, 1)*x9 + hvp1_r(3, 1)*x1 - hvp2_rr(1, 3, 1)*inv_pd + &
               qn0(1)*x26 + qn1_r(1, 1)*x10 + qn1_r(3, 1)*x6 + qn2_rr(1, 3, 1)*x2
            hvp_f3_rr_rA(1, 3, 1) = t_hvp_f3_rr_rA_020
            hvp_f3_rr_rA(3, 1, 1) = t_hvp_f3_rr_rA_020
            t_hvp_f3_rr_rA_021 = &
               hvp0(2)*x24 + hvp1_r(1, 2)*x9 + hvp1_r(3, 2)*x1 - hvp2_rr(1, 3, 2)*inv_pd + &
               qn0(2)*x26 + qn1_r(1, 2)*x10 + qn1_r(3, 2)*x6 + qn2_rr(1, 3, 2)*x2
            hvp_f3_rr_rA(1, 3, 2) = t_hvp_f3_rr_rA_021
            hvp_f3_rr_rA(3, 1, 2) = t_hvp_f3_rr_rA_021
            t_hvp_f3_rr_rA_022 = &
               hvp0(3)*x24 + hvp1_r(1, 3)*x9 + hvp1_r(3, 3)*x1 - hvp2_rr(1, 3, 3)*inv_pd + &
               qn0(3)*x26 + qn1_r(1, 3)*x10 + qn1_r(3, 3)*x6 + qn2_rr(1, 3, 3)*x2
            hvp_f3_rr_rA(1, 3, 3) = t_hvp_f3_rr_rA_022
            hvp_f3_rr_rA(3, 1, 3) = t_hvp_f3_rr_rA_022
            hvp_f3_rr_rA(2, 2, 1) = &
               hvp0(1)*x29 + hvp1_r(2, 1)*x27 - hvp2_rr(2, 2, 1)*inv_pd + qn0(1)*x32 + qn1_r(2, &
               1)*x31 + qn2_rr(2, 2, 1)*x2
            hvp_f3_rr_rA(2, 2, 2) = &
               hvp0(2)*x29 + hvp1_r(2, 2)*x27 - hvp2_rr(2, 2, 2)*inv_pd + qn0(2)*x32 + qn1_r(2, &
               2)*x31 + qn2_rr(2, 2, 2)*x2
            hvp_f3_rr_rA(2, 2, 3) = &
               hvp0(3)*x29 + hvp1_r(2, 3)*x27 - hvp2_rr(2, 2, 3)*inv_pd + qn0(3)*x32 + qn1_r(2, &
               3)*x31 + qn2_rr(2, 2, 3)*x2
            t_hvp_f3_rr_rA_120 = &
               hvp0(1)*x34 + hvp1_r(2, 1)*x9 + hvp1_r(3, 1)*x7 - hvp2_rr(2, 3, 1)*inv_pd + &
               qn0(1)*x35 + qn1_r(2, 1)*x10 + qn1_r(3, 1)*x8 + qn2_rr(2, 3, 1)*x2
            hvp_f3_rr_rA(2, 3, 1) = t_hvp_f3_rr_rA_120
            hvp_f3_rr_rA(3, 2, 1) = t_hvp_f3_rr_rA_120
            t_hvp_f3_rr_rA_121 = &
               hvp0(2)*x34 + hvp1_r(2, 2)*x9 + hvp1_r(3, 2)*x7 - hvp2_rr(2, 3, 2)*inv_pd + &
               qn0(2)*x35 + qn1_r(2, 2)*x10 + qn1_r(3, 2)*x8 + qn2_rr(2, 3, 2)*x2
            hvp_f3_rr_rA(2, 3, 2) = t_hvp_f3_rr_rA_121
            hvp_f3_rr_rA(3, 2, 2) = t_hvp_f3_rr_rA_121
            t_hvp_f3_rr_rA_122 = &
               hvp0(3)*x34 + hvp1_r(2, 3)*x9 + hvp1_r(3, 3)*x7 - hvp2_rr(2, 3, 3)*inv_pd + &
               qn0(3)*x35 + qn1_r(2, 3)*x10 + qn1_r(3, 3)*x8 + qn2_rr(2, 3, 3)*x2
            hvp_f3_rr_rA(2, 3, 3) = t_hvp_f3_rr_rA_122
            hvp_f3_rr_rA(3, 2, 3) = t_hvp_f3_rr_rA_122
            hvp_f3_rr_rA(3, 3, 1) = &
               hvp0(1)*x38 + hvp1_r(3, 1)*x36 - hvp2_rr(3, 3, 1)*inv_pd + qn0(1)*x41 + qn1_r(3, &
               1)*x40 + qn2_rr(3, 3, 1)*x2
            hvp_f3_rr_rA(3, 3, 2) = &
               hvp0(2)*x38 + hvp1_r(3, 2)*x36 - hvp2_rr(3, 3, 2)*inv_pd + qn0(2)*x41 + qn1_r(3, &
               2)*x40 + qn2_rr(3, 3, 2)*x2
            hvp_f3_rr_rA(3, 3, 3) = &
               hvp0(3)*x38 + hvp1_r(3, 3)*x36 - hvp2_rr(3, 3, 3)*inv_pd + qn0(3)*x41 + qn1_r(3, &
               3)*x40 + qn2_rr(3, 3, 3)*x2
         end block
      end select

   end subroutine cfc_hvp_eval

end module moist_cavity_drop_lsf_cfc_kernel
